package lower

import (
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/system-inc/adamic/internal/ir"
)

func namespaceStatements(declaration *ast.Node) []*ast.Node {
	body := declaration.AsModuleDeclaration().Body
	if body == nil {
		return nil
	}
	if body.Kind == ast.KindModuleDeclaration {
		return []*ast.Node{body}
	}
	return body.AsModuleBlock().Statements.Nodes
}

func namespaceRuntime(declaration *ast.Node) bool {
	// Ambient declarations describe host values, not executable namespace bodies.
	// The context flag includes nested declarations without their own declare token.
	if declaration.Flags&ast.NodeFlagsAmbient != 0 || ast.HasSyntacticModifier(declaration, ast.ModifierFlagsAmbient) || ast.GetSourceFileOfNode(declaration).IsDeclarationFile {
		return false
	}
	for _, member := range namespaceStatements(declaration) {
		switch member.Kind {
		case ast.KindInterfaceDeclaration, ast.KindTypeAliasDeclaration, ast.KindEmptyStatement:
		case ast.KindModuleDeclaration:
			if namespaceRuntime(member) {
				return true
			}
		default:
			return true
		}
	}
	return false
}

// Flatten scoped declarations, never names: the checker's symbols retain every namespace and
// private binding's identity. The qualified-only subset cannot observe a namespace object.
func namespaceDeclarations(statements []*ast.Node) []*ast.Node {
	result := []*ast.Node{}
	for _, statement := range statements {
		if statement.Kind == ast.KindModuleDeclaration {
			result = append(result, namespaceDeclarations(namespaceStatements(statement))...)
		} else {
			result = append(result, statement)
		}
	}
	return result
}

func (l *lowering) namespaceDeclaration(node *ast.Node) *ast.Node {
	symbol := l.symbol(node)
	if symbol == nil {
		return nil
	}
	for _, declaration := range symbol.Declarations {
		if declaration.Kind == ast.KindModuleDeclaration && ast.IsIdentifier(declaration.Name()) {
			return declaration
		}
	}
	return nil
}

func (l *lowering) namespaceMember(node *ast.Node) bool {
	module := false
	if node.Kind == ast.KindPropertyAccessExpression || node.Kind == ast.KindElementAccessExpression {
		module = l.moduleNamespace(node.Expression())
		if !module && l.namespaceDeclaration(node.Expression()) == nil {
			return false
		}
	}
	symbol := l.symbol(node)
	if symbol == nil {
		return false
	}
	for _, declaration := range symbol.Declarations {
		parent := declaration.Parent
		if declaration.Kind == ast.KindVariableDeclaration {
			parent = parent.Parent.Parent
		}
		if parent != nil && (parent.Kind == ast.KindModuleBlock || module && parent.Kind == ast.KindSourceFile) {
			return true
		}
	}
	return false
}

func (l *lowering) namespaceExpression(node *ast.Node) (ir.Expression, bool, error) {
	if node.Kind != ast.KindPropertyAccessExpression && node.Kind != ast.KindElementAccessExpression || !l.namespaceMember(node) {
		return nil, false, nil
	}
	if node.Kind == ast.KindElementAccessExpression {
		return nil, true, l.notYet(node, "a computed namespace member; use a qualified name")
	}
	if node.AsPropertyAccessExpression().QuestionDotToken != nil || node.Flags&ast.NodeFlagsOptionalChain != 0 {
		return nil, true, l.notYet(node, "an optional namespace read; use a qualified name after initialization")
	}
	if function, found := l.functions[l.symbol(node)]; found {
		value, err := l.functionValue(node, function)
		if err == nil {
			value = l.namespaceReadyValue(node, value)
		}
		return value, true, err
	}
	if local, found := l.local(node); found {
		read, err := l.localRead(node, local)
		if err != nil {
			return nil, true, err
		}
		return l.namespaceReadyValue(node, read), true, nil
	}
	return nil, true, l.notYet(node, "a namespace member without a lowered binding")
}

func (l *lowering) namespaceValueNode(node *ast.Node) bool {
	if parent := node.Parent; parent != nil && parent.Kind == ast.KindPropertyAccessExpression && parent.Name() == node {
		return false
	}
	if !l.isExpression(node) || ast.IsDeclarationName(node) {
		return false
	}
	for parent := node.Parent; parent != nil; parent = parent.Parent {
		if ast.IsTypeNode(parent) || parent.Kind == ast.KindImportDeclaration || parent.Kind == ast.KindExportDeclaration {
			return false
		}
		if ast.IsStatement(parent) {
			break
		}
	}
	return true
}

func (l *lowering) namespaceRefusal(node *ast.Node) error {
	if err := l.moduleNamespaceRefusal(node); err != nil {
		return err
	}
	if node.Kind == ast.KindModuleDeclaration {
		if !ast.IsIdentifier(node.Name()) || ast.HasSyntacticModifier(node, ast.ModifierFlagsAmbient) {
			return l.notYet(node, "an ambient namespace or external module; use named file imports")
		}
		if node.Parent.Kind != ast.KindSourceFile && node.Parent.Kind != ast.KindModuleBlock && node.Parent.Kind != ast.KindModuleDeclaration {
			return l.notYet(node, "a namespace outside module scope")
		}
		symbol := l.symbol(node.Name())
		for _, declaration := range symbol.Declarations {
			if declaration == node || declaration.Kind == ast.KindInterfaceDeclaration || declaration.Kind == ast.KindTypeAliasDeclaration {
				continue
			}
			if declaration.Kind == ast.KindFunctionDeclaration && declaration.Parent == node.Parent {
				if namespaceOwnThis(declaration) {
					return &Refused{Where: l.program.Where(declaration), What: "this in a callable namespace function; qualified and detached calls have different receivers", Fix: "pass the state explicitly"}
				}
				for _, parameter := range declaration.Parameters() {
					if parameter.Name().Text() == "this" {
						return l.notYet(parameter, "an explicit callable-namespace this parameter; pass state explicitly")
					}
				}
				continue
			}
			return l.notYet(node, "a reopened namespace or namespace merged with a runtime value; put the declarations in one namespace or use a module")
		}
		for _, member := range namespaceStatements(node) {
			if l.namespaceMergedFunction(node.Name()) && ast.HasSyntacticModifier(member, ast.ModifierFlagsExport) {
				if member.Kind == ast.KindVariableStatement {
					for _, variable := range member.AsVariableStatement().DeclarationList.AsVariableDeclarationList().Declarations.Nodes {
						if variable.Name() != nil && callableNamespaceIntrinsic(variable.Name().Text()) {
							return l.notYet(variable, "a callable namespace export colliding with a function intrinsic")
						}
					}
				} else if member.Name() != nil && callableNamespaceIntrinsic(member.Name().Text()) {
					return l.notYet(member, "a callable namespace export colliding with a function intrinsic")
				}
			}
			switch member.Kind {
			case ast.KindInterfaceDeclaration, ast.KindTypeAliasDeclaration, ast.KindEmptyStatement, ast.KindModuleDeclaration, ast.KindClassDeclaration, ast.KindEnumDeclaration:
			case ast.KindExpressionStatement, ast.KindBlock, ast.KindIfStatement, ast.KindForStatement, ast.KindWhileStatement, ast.KindDoStatement, ast.KindForOfStatement, ast.KindSwitchStatement:
				// Statement lowering keeps module evaluation order. Calls still pass preflight.
			case ast.KindFunctionDeclaration:
				if namespaceOwnThis(member) {
					return &Refused{Where: l.program.Where(member), What: "this in a namespace function; a qualified call and a detached call have different receivers", Fix: "pass the state as an explicit parameter instead of using this"}
				}
				for _, parameter := range member.Parameters() {
					if parameter.Name().Kind == ast.KindThisKeyword || parameter.Name().Text() == "this" {
						return l.notYet(parameter, "an explicit namespace-function this parameter; pass state explicitly")
					}
				}
			case ast.KindVariableStatement:
				list := member.AsVariableStatement().DeclarationList
				for _, variable := range list.AsVariableDeclarationList().Declarations.Nodes {
					if !ast.IsIdentifier(variable.Name()) && (list.Flags&ast.NodeFlagsBlockScoped != 0 || !namespaceObjectBindings(variable.Name())) {
						return l.notYet(variable, "destructuring inside a namespace; use plain singleton bindings")
					}
				}
			default:
				return l.notYet(member, "an unsupported namespace statement or declaration")
			}
		}
	}
	if node.Kind == ast.KindVariableDeclarationList && node.Flags&ast.NodeFlagsBlockScoped == 0 && !namespaceVariable(node) {
		for parent := node.Parent; parent != nil; parent = parent.Parent {
			if ast.IsFunctionLike(parent) {
				break
			}
			if parent.Kind == ast.KindModuleBlock {
				return l.notYet(node, "var inside namespace control flow; direct singleton var is hoisted, block var is not yet modeled")
			}
		}
	}
	if l.namespaceValueNode(node) && l.namespaceDeclaration(node) != nil {
		parent := node.Parent
		if l.namespaceMergedFunction(node) {
			if l.callableNamespaceUse(node) {
				return nil
			}
			return l.notYet(node, "observing a callable namespace object; only direct calls, fixed qualified members, typeof and canonical function identity are represented")
		}
		if parent == nil || parent.Kind != ast.KindPropertyAccessExpression || parent.AsPropertyAccessExpression().Expression != node {
			return l.notYet(node, "a namespace object used as a value; no runtime container is emitted, so identity, receiver behavior, live export aliases and staged properties are not represented; use qualified members or named module imports")
		}
	}
	if l.isExpression(node) && l.namespaceMember(node) {
		parent := node.Parent
		if parent != nil && parent.Kind == ast.KindBinaryExpression && parent.AsBinaryExpression().Left == node && ast.IsAssignmentOperator(parent.AsBinaryExpression().OperatorToken.Kind) {
			if node.Kind == ast.KindPropertyAccessExpression || node.Kind == ast.KindElementAccessExpression {
				symbol := l.symbol(node)
				mutable := false
				for _, declaration := range symbol.Declarations {
					if declaration.Kind == ast.KindVariableDeclaration && declaration.Parent.Flags&ast.NodeFlagsConst == 0 {
						mutable = true
					}
				}
				if !mutable {
					return l.notYet(node, "replacing a namespace export; exported functions and constants have fixed identity")
				}
			}
		}
	}
	return nil
}

// Follow statically known callees before executing a module statement. An unresolved
// edge keeps namespace reads checked at runtime; it is never proof of no effects.
func (l *lowering) namespaceInitialization(modules []*ast.SourceFile) error {
	initialized := map[*ast.Node]bool{}
	graph := namespaceCallGraph{lowering: l, functions: map[*ast.Node]*namespaceCallNode{}}
	checkCall := func(target *ast.Node) error {
		for declaration, read := range graph.reach(target) {
			if !initialized[declaration] {
				if declaration.Kind == ast.KindEnumDeclaration {
					return l.notYet(read, "reading an enum before its runtime initialization; move the call after the enum declaration")
				}
				return l.notYet(read, "a namespace read before runtime initialization, directly or through a reachable call; move that read or call after the namespace declaration")
			}
		}
		return nil
	}
	var visit func(*ast.Node) error
	visit = func(node *ast.Node) error {
		if node == nil || ast.IsTypeNode(node) || ast.IsFunctionLike(node) {
			return nil
		}
		if branch := l.literalCallableBranch(node); branch != nil {
			return visit(branch)
		}
		if ast.IsClassLike(node) {
			for _, clause := range nodesOf(node.AsClassDeclaration().HeritageClauses) {
				if clause.AsHeritageClause().Token == ast.KindExtendsKeyword {
					for _, element := range clause.AsHeritageClause().Types.Nodes {
						if err := visit(element.AsExpressionWithTypeArguments().Expression); err != nil {
							return err
						}
					}
				}
			}
			// Instance fields and constructor bodies execute at new, not at the
			// declaration. Unknown construction keeps the checks in those bodies.
			for _, member := range node.AsClassDeclaration().Members.Nodes {
				if ast.HasStaticModifier(member) || member.Kind == ast.KindClassStaticBlockDeclaration {
					if err := visit(member); err != nil {
						return err
					}
				}
			}
			return nil
		}
		if node.Kind == ast.KindModuleDeclaration {
			for _, statement := range namespaceStatements(node) {
				if err := visit(statement); err != nil {
					return err
				}
			}
			initialized[node] = true
			return nil
		}
		// The enum object exists while its own member assignments execute.
		if node.Kind == ast.KindEnumDeclaration {
			initialized[node] = true
		}
		if l.namespaceValueNode(node) {
			if declaration := l.namespaceRuntimeEnum(node); declaration != nil && !initialized[declaration] {
				return l.notYet(node, "reading an enum before its runtime initialization; move the call after the enum declaration")
			}
			if declaration := l.namespaceDeclaration(node); declaration != nil && namespaceRuntime(declaration) && !initialized[declaration] {
				return l.notYet(node, "a namespace read before runtime initialization, directly or through a reachable call; move that read or call after the namespace declaration")
			}
		}
		if node.Kind == ast.KindCallExpression || node.Kind == ast.KindNewExpression {
			if target := l.namespaceCallable(node.Expression()); target != nil {
				if err := checkCall(target); err != nil {
					return err
				}
			}
			// Library operations may invoke callbacks. A known callback participates in
			// the same graph; unknown values retain checks in their eventual bodies.
			for _, argument := range node.Arguments() {
				if target := l.namespaceCallable(argument); target != nil {
					if err := checkCall(target); err != nil {
						return err
					}
				}
			}
		}
		var found error
		node.ForEachChild(func(child *ast.Node) bool { found = visit(child); return found != nil })
		if node.Kind == ast.KindEnumDeclaration {
			initialized[node] = true
		}
		return found
	}
	for _, module := range modules {
		for _, statement := range module.Statements.Nodes {
			if err := visit(statement); err != nil {
				return err
			}
		}
	}
	return nil
}

// Mutable aliases, parameters and virtual methods are unresolved edges. Only
// direct functions and immutable initializer chains identify a single body.
func (l *lowering) namespaceCallable(callee *ast.Node) *ast.Node {
	seen := map[*ast.Symbol]bool{}
	for callee != nil {
		callee = ast.SkipParentheses(callee)
		if branch := l.literalCallableBranch(callee); branch != nil {
			callee = branch
			continue
		}
		if callee.Kind == ast.KindArrowFunction || callee.Kind == ast.KindFunctionExpression {
			return callee
		}
		symbol := l.symbol(callee)
		if symbol == nil || seen[symbol] || symbol.ValueDeclaration == nil {
			return nil
		}
		seen[symbol] = true
		declaration := symbol.ValueDeclaration
		switch declaration.Kind {
		case ast.KindClassDeclaration:
			return declaration
		case ast.KindFunctionDeclaration:
			if declaration.Body() != nil {
				return declaration
			}
			return nil
		case ast.KindVariableDeclaration:
			if declaration.Parent.Flags&ast.NodeFlagsConst == 0 {
				return nil
			}
			callee = declaration.Initializer()
		case ast.KindPropertyAssignment:
			if !l.checker.IsReadonlySymbol(symbol) {
				return nil
			}
			callee = declaration.Initializer()
		default:
			return nil
		}
	}
	return nil
}

// A generated boolean starts false before module evaluation and becomes true
// only after the namespace body completes. Checks use ordinary IR and the
// namespace-property TypeError, rather than reading native zero export storage.
func (l *lowering) namespaceReadyLocal(declaration *ast.Node) int {
	symbol := l.symbol(declaration.Name())
	if local, found := l.locals[symbol]; found {
		return local
	}
	if l.locals == nil {
		l.locals = map[*ast.Symbol]int{}
	}
	local := len(l.result.Locals)
	l.locals[symbol] = local
	l.result.Locals = append(l.result.Locals, ir.Local{Name: declaration.Name().Text(), Type: ir.Boolean, Global: true, Function: -1})
	l.forwarderValues = append(l.forwarderValues, ir.Declare{Local: local, Value: ir.BooleanConstant{Value: false}})
	return local
}

func (l *lowering) namespaceReadyReads(node *ast.Node, writing bool) []ir.Expression {
	checks := []ir.Expression{}
	for node != nil && ast.SkipParentheses(node).Kind == ast.KindPropertyAccessExpression {
		node = ast.SkipParentheses(node)
		member := node.Name().Text()
		setting := writing
		writing = false
		node = ast.SkipParentheses(node.Expression())
		if declaration := l.namespaceDeclaration(node); declaration != nil && namespaceRuntime(declaration) {
			b := l.libraryArrayBuilder([]ir.Expression{ir.Read{Local: l.namespaceReadyLocal(declaration), Of: ir.Boolean}})
			message := "TypeError: Cannot read properties of undefined (reading '" + member + "')"
			if setting {
				message = "TypeError: Cannot set properties of undefined (setting '" + member + "')"
			}
			b.body = append(b.body, ir.If{Condition: ir.Unary{Operator: ir.Not, Operand: b.read(b.parameters[0])}, Then: []ir.Statement{ir.Panic{Message: ir.StringConstant{Index: l.constant(message)}}}})
			// The outer container is read first in Outer.Inner.member.
			checks = append([]ir.Expression{b.finish("namespace_ready", ir.BooleanConstant{Value: true})}, checks...)
		}
	}
	return checks
}

func (l *lowering) namespaceReadyValue(node *ast.Node, value ir.Expression) ir.Expression {
	checks := l.namespaceReadyReads(node, false)
	if len(checks) == 0 {
		return value
	}
	b := l.libraryArrayBuilder(append(checks, value))
	return b.finish("namespace_read", b.read(b.parameters[len(checks)]))
}

// Run readiness before evaluating the call. Keep the call itself intact so its
// counted dispatch, spread layout and argument fitting remain at the existing boundary.
func (l *lowering) namespaceReadyCall(node *ast.Node, value ir.Expression) ir.Expression {
	checks := l.namespaceReadyReads(node, false)
	if len(checks) == 0 {
		return value
	}
	body := make([]ir.Statement, 0, len(checks)+1)
	for _, check := range checks {
		body = append(body, ir.Evaluate{Value: check})
	}
	if value.Type() == 0 {
		body = append(body, ir.Evaluate{Value: value})
		value = ir.Undefined{}
	}
	return ir.Effects{Body: body, Result: value}
}

// namespaceVariable identifies direct singleton storage, excluding function-local var.
func namespaceVariable(list *ast.Node) bool {
	return list.Parent != nil && list.Parent.Parent != nil && list.Parent.Parent.Kind == ast.KindModuleBlock
}

func (l *lowering) namespaceBody(node *ast.Node) ([]ir.Statement, error) {
	hoisted := []ir.Statement{}
	seen := map[int]bool{}
	for _, statement := range namespaceStatements(node) {
		if statement.Kind != ast.KindVariableStatement {
			continue
		}
		list := statement.AsVariableStatement().DeclarationList
		if list.Flags&ast.NodeFlagsBlockScoped != 0 {
			continue
		}
		for _, declaration := range list.AsVariableDeclarationList().Declarations.Nodes {
			names := []*ast.Node{declaration.Name()}
			if !ast.IsIdentifier(declaration.Name()) {
				if !namespaceObjectBindings(declaration.Name()) {
					return nil, l.notYet(declaration.Name(), "destructuring inside a namespace; only flat object var bindings are hoisted")
				}
				names = nil
				for _, binding := range declaration.Name().AsBindingPattern().Elements.Nodes {
					names = append(names, binding.Name())
				}
			}
			for _, name := range names {
				local, err := l.declareLocal(name)
				if err != nil {
					return nil, err
				}
				if seen[local] {
					continue
				}
				seen[local] = true
				var value ir.Expression
				if l.includesUndefined(l.checker.GetTypeAtLocation(name)) {
					value = fit(ir.Undefined{Of: l.result.Locals[local].Type}, l.result.Locals[local].Type)
				}
				hoisted = append(hoisted, ir.Declare{Local: local, Value: value})
			}
		}
	}
	body, err := l.statements(namespaceStatements(node))
	if err != nil {
		return nil, err
	}
	if namespaceRuntime(node) {
		body = append(body, ir.Assign{Local: l.namespaceReadyLocal(node), Value: ir.BooleanConstant{Value: true}})
	}
	return append(hoisted, body...), nil
}

// The parser's factory destructuring declares symbols on the renamed identifiers,
// not on the ObjectBindingPattern. Other binding forms retain their own NotYet.
func namespaceObjectBindings(pattern *ast.Node) bool {
	if pattern.Kind != ast.KindObjectBindingPattern {
		return false
	}
	for _, binding := range pattern.AsBindingPattern().Elements.Nodes {
		declared := binding.AsBindingElement()
		if !ast.IsIdentifier(binding.Name()) || declared.Initializer != nil || declared.DotDotDotToken != nil {
			return false
		}
		if declared.PropertyName != nil && !ast.IsIdentifier(declared.PropertyName) && declared.PropertyName.Kind != ast.KindStringLiteral {
			return false
		}
	}
	return true
}

func (l *lowering) namespaceReadyStatements(node *ast.Node, writing bool) []ir.Statement {
	statements := []ir.Statement{}
	for _, check := range l.namespaceReadyReads(node, writing) {
		statements = append(statements, ir.Evaluate{Value: check})
	}
	return statements
}

package lower

import "github.com/microsoft/TypeScript/tsc/shim/ast"

// Arrows inherit this, but a nested ordinary function, object method or class
// owns a separate receiver. Its body is checked by that construct's lowering.
func namespaceOwnThis(declaration *ast.Node) bool {
	var visit func(*ast.Node) bool
	visit = func(node *ast.Node) bool {
		if node == nil || ast.IsTypeNode(node) {
			return false
		}
		if ast.IsClassLike(node) || ast.IsFunctionLike(node) && node.Kind != ast.KindArrowFunction {
			return false
		}
		if node.Kind == ast.KindThisKeyword {
			return true
		}
		return node.ForEachChild(visit)
	}
	return visit(declaration.Body())
}

internal/lower/namespace_callable.go:
package lower

import "github.com/microsoft/TypeScript/tsc/shim/ast"

func (l *lowering) namespaceMergedFunction(node *ast.Node) bool {
	symbol := l.symbol(node)
	if symbol == nil || l.namespaceDeclaration(node) == nil {
		return false
	}
	for _, declaration := range symbol.Declarations {
		if declaration.Kind == ast.KindFunctionDeclaration {
			return true
		}
	}
	return false
}

// A closure represents the callable identity, but has no attached object storage.
// Only uses that cannot observe that omitted container are admitted.
func (l *lowering) callableNamespaceUse(node *ast.Node) bool {
	if called(node) {
		return true
	}
	use := node
	for use.Parent != nil && use.Parent.Kind == ast.KindParenthesizedExpression {
		use = use.Parent
	}
	parent := use.Parent
	if parent == nil {
		return false
	}
	if parent.Kind == ast.KindTypeOfExpression {
		return true
	}
	if parent.Kind == ast.KindPropertyAccessExpression && parent.Expression() == use && l.namespaceMember(parent) {
		return true
	}
	if parent.Kind == ast.KindBinaryExpression {
		binary := parent.AsBinaryExpression()
		if binary.OperatorToken.Kind == ast.KindEqualsEqualsEqualsToken || binary.OperatorToken.Kind == ast.KindExclamationEqualsEqualsToken {
			return l.namespaceFixedFunction(binary.Left) && l.namespaceFixedFunction(binary.Right)
		}
	}
	return false
}

func (l *lowering) namespaceFixedFunction(node *ast.Node) bool {
	node = ast.SkipParentheses(node)
	if node.Kind != ast.KindIdentifier && node.Kind != ast.KindPropertyAccessExpression {
		return false
	}
	symbol := l.symbol(node)
	if symbol == nil {
		return false
	}
	for _, declaration := range symbol.Declarations {
		if declaration.Kind == ast.KindFunctionDeclaration && (declaration.Parent.Kind == ast.KindModuleBlock || l.namespaceMergedFunction(node)) {
			return true
		}
	}
	return false
}

func callableNamespaceIntrinsic(name string) bool {
	switch name {
	case "name", "length", "prototype", "caller", "arguments", "call", "apply", "bind", "toString":
		return true
	}
	return false
}

internal/lower/predicates_proof.go:
package lower

import (
	"fmt"

	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
)

// A tag proof certifies membership in the tag set only. Admission must preserve
// a checked view for the target's remaining fields; this is not a shape proof.
type predicateProof struct{ TaggedView bool }

type predicateTruth uint8

const (
	predicateTrue   predicateTruth = 1
	predicateFalse  predicateTruth = 2
	predicateEither predicateTruth = 3
)

type predicateVerifier struct {
	l          *lowering
	field      string
	truthiness bool
	cells      []string
	summaries  map[*ast.Node][]predicateTruth
}

type predicatePath struct {
	cell   int
	locals map[*ast.Symbol]predicateTruth
}

func predicateFailure(l *lowering, node *ast.Node, path string) error {
	where := ""
	if node != nil {
		where = l.program.Where(node)
	}
	return &Refused{Where: where, What: "an unproven type predicate", Fix: path + "; return a boolean and narrow at the caller (adamic/no-type-predicate)"}
}

// provePredicate starts with no helper facts. Only independently verified bodies
// become summaries. Iteration terminates when no new body can be discharged;
// cycles and opaque calls never acquire a summary from their annotations.
func (l *lowering) provePredicate(node *ast.Node) (predicateProof, error) {
	proof := predicateProof{}
	if node == nil || node.Kind != ast.KindTypePredicate || node.Parent == nil || !ast.IsFunctionLike(node.Parent) || node.Parent.Body() == nil {
		return proof, predicateFailure(l, node, "no implementation body proves a return path")
	}
	v := &predicateVerifier{l: l, summaries: map[*ast.Node][]predicateTruth{}}
	if node.AsTypePredicateNode().Type == nil {
		if node.AsTypePredicateNode().AssertsModifier != nil {
			return l.proveConditionAssertion(node)
		}
		return proof, predicateFailure(l, node, "an assertion without a target type is not proved")
	}
	target := l.checker.GetTypeAtLocation(node.AsTypePredicateNode().Type)
	if target.Flags()&(checker.TypeFlagsObject|checker.TypeFlagsUnion) != 0 && v.kindTarget(target) {
		v.field = "kind"
		proof.TaggedView = true
	} else if !predicatePrimitiveTarget(target) {
		return proof, predicateFailure(l, node, "the target has an unsupported runtime contract")
	}
	if v.field == "" {
		v.cells = []string{"string", "number", "boolean", "undefined", "object", "function", "symbol", "bigint"}
	} else {
		v.cells = []string{"<other kind>"}
	}
	var declarations []*ast.Node
	var visit ast.Visitor
	visit = func(n *ast.Node) bool {
		if ast.IsFunctionLike(n) && n.Type() != nil && n.Type().Kind == ast.KindTypePredicate && n.Body() != nil {
			declarations = append(declarations, n)
			if v.field != "" {
				v.collectKinds(n)
			}
		}
		n.ForEachChild(visit)
		return false
	}
	for _, file := range l.program.Files() {
		file.AsNode().ForEachChild(visit)
	}
	var last error
	for {
		changed := false
		for _, declaration := range declarations {
			if _, ok := v.summaries[declaration]; ok {
				continue
			}
			summary, err := v.verify(declaration)
			if declaration == node.Parent {
				last = err
			}
			if err == nil {
				v.summaries[declaration] = summary
				changed = true
			}
		}
		if _, ok := v.summaries[node.Parent]; ok {
			return proof, nil
		}
		if !changed {
			break
		}
	}
	if last == nil {
		last = predicateFailure(l, node, "unconverged helper proof")
	}
	return predicateProof{}, last
}

func predicatePrimitiveTarget(t *checker.Type) bool {
	if t.Flags()&checker.TypeFlagsUnion != 0 {
		for _, m := range t.Types() {
			if !predicatePrimitiveTarget(m) {
				return false
			}
		}
		return true
	}
	// Literal refinements need value partitions, not just typeof partitions.
	return t.Flags()&(checker.TypeFlagsString|checker.TypeFlagsNumber|checker.TypeFlagsBoolean|checker.TypeFlagsUndefined) != 0 && t.Flags()&(checker.TypeFlagsLiteral|checker.TypeFlagsAny|checker.TypeFlagsUnknown|checker.TypeFlagsTypeParameter) == 0
}

func (v *predicateVerifier) kindTarget(t *checker.Type) bool {
	if t.Flags()&checker.TypeFlagsUnion != 0 {
		for _, m := range t.Types() {
			if !v.kindTarget(m) {
				return false
			}
		}
		return true
	}
	return t.Flags()&checker.TypeFlagsObject != 0 && !isClassInstance(t) && v.l.fieldLiteral(t, "kind") != nil
}

func predicateLiteral(t *checker.Type) (string, bool) {
	if t.Flags()&(checker.TypeFlagsStringLiteral|checker.TypeFlagsNumberLiteral|checker.TypeFlagsBooleanLiteral) == 0 {
		return "", false
	}
	return fmt.Sprintf("%T:%v", t.AsLiteralType().Value(), t.AsLiteralType().Value()), true
}

func (v *predicateVerifier) addKind(t *checker.Type) {
	key, ok := predicateLiteral(t)
	if !ok {
		return
	}
	for _, cell := range v.cells {
		if cell == key {
			return
		}
	}
	v.cells = append(v.cells, key)
}

func (v *predicateVerifier) collectKinds(declaration *ast.Node) {
	var addTarget func(*checker.Type)
	addTarget = func(t *checker.Type) {
		if t.Flags()&checker.TypeFlagsUnion != 0 {
			for _, m := range t.Types() {
				addTarget(m)
			}
			return
		}
		if literal := v.l.fieldLiteral(t, "kind"); literal != nil {
			v.addKind(literal)
		}
	}
	predicate := declaration.Type().AsTypePredicateNode()
	if predicate.Type != nil {
		addTarget(v.l.checker.GetTypeAtLocation(predicate.Type))
	}
	var visit ast.Visitor
	visit = func(n *ast.Node) bool {
		if n.Kind == ast.KindBinaryExpression {
			b := n.AsBinaryExpression()
			if b.OperatorToken.Kind == ast.KindEqualsEqualsEqualsToken || b.OperatorToken.Kind == ast.KindExclamationEqualsEqualsToken {
				v.addKind(v.l.checker.GetTypeAtLocation(b.Left))
				v.addKind(v.l.checker.GetTypeAtLocation(b.Right))
			}
		}
		n.ForEachChild(visit)
		return false
	}
	declaration.Body().ForEachChild(visit)
}

func (v *predicateVerifier) wanted(t *checker.Type, cell string) (bool, bool) {
	if t.Flags()&checker.TypeFlagsUnion != 0 {
		answer := false
		for _, m := range t.Types() {
			yes, ok := v.wanted(m, cell)
			if !ok {
				return false, false
			}
			answer = answer || yes
		}
		return answer, true
	}
	if v.field != "" {
		if !v.kindTarget(t) {
			return false, false
		}
		key, ok := predicateLiteral(v.l.fieldLiteral(t, v.field))
		return key == cell, ok
	}
	if !predicatePrimitiveTarget(t) {
		return false, false
	}
	kinds := map[string]checker.TypeFlags{"string": checker.TypeFlagsString, "number": checker.TypeFlagsNumber, "boolean": checker.TypeFlagsBoolean, "undefined": checker.TypeFlagsUndefined}
	return t.Flags()&kinds[cell] != 0, true
}

func (v *predicateVerifier) parameter(declaration *ast.Node) *ast.Symbol {
	predicate := declaration.Type().AsTypePredicateNode()
	for _, p := range declaration.Parameters() {
		if ast.IsIdentifier(p.Name()) && p.Name().Text() == predicate.ParameterName.Text() {
			return v.l.checker.GetSymbolAtLocation(p.Name())
		}
	}
	return nil
}

func (v *predicateVerifier) verify(declaration *ast.Node) ([]predicateTruth, error) {
	parameter := v.parameter(declaration)
	if parameter == nil || len(declaration.TypeParameters()) != 0 {
		return nil, predicateFailure(v.l, declaration, "a generic or non-parameter target has no body proof")
	}
	for _, parameter := range declaration.Parameters() {
		declared := parameter.AsParameterDeclaration()
		if declared.Initializer != nil || declared.DotDotDotToken != nil || !ast.IsIdentifier(parameter.Name()) {
			return nil, predicateFailure(v.l, parameter, "parameter initialization may mutate the tested input before this return path")
		}
	}
	predicate := declaration.Type().AsTypePredicateNode()
	if predicate.Type == nil {
		return nil, predicateFailure(v.l, declaration, "an assertion without a target type is not proved")
	}
	target := v.l.checker.GetTypeAtLocation(predicate.Type)
	summary := make([]predicateTruth, len(v.cells))
	for i, cell := range v.cells {
		wanted, ok := v.wanted(target, cell)
		if !ok {
			return nil, predicateFailure(v.l, declaration, "the target has an unsupported runtime contract")
		}
		path := predicatePath{cell: i, locals: map[*ast.Symbol]predicateTruth{}}
		check := func(n *ast.Node, result predicateTruth) error {
			if predicate.AssertsModifier != nil {
				if !wanted {
					return predicateFailure(v.l, n, "normal return does not establish the asserted target")
				}
			} else {
				if result&predicateTrue != 0 && !wanted {
					return predicateFailure(v.l, n, "true return does not establish the target")
				}
				if result&predicateFalse != 0 && wanted {
					return predicateFailure(v.l, n, "false return does not exclude the target")
				}
			}
			summary[i] |= result
			return nil
		}
		body := declaration.Body()
		if body.Kind != ast.KindBlock {
			result, err := v.expression(body, parameter, path)
			if err != nil {
				return nil, err
			}
			if err = check(body, result); err != nil {
				return nil, err
			}
			continue
		}
		paths, err := v.statements(body.AsBlock().Statements.Nodes, parameter, []predicatePath{path}, check)
		if err != nil {
			return nil, err
		}
		if len(paths) > 0 {
			if predicate.AssertsModifier == nil {
				return nil, predicateFailure(v.l, body, "normal return has no boolean result")
			}
			if err = check(body, predicateTrue); err != nil {
				return nil, err
			}
		}
	}
	return summary, nil
}

func predicateNot(t predicateTruth) predicateTruth {
	return (t&predicateTrue)<<1 | (t&predicateFalse)>>1
}
func predicateCombine(a, b predicateTruth, and bool) predicateTruth {
	var result predicateTruth
	for _, x := range []predicateTruth{predicateTrue, predicateFalse} {
		for _, y := range []predicateTruth{predicateTrue, predicateFalse} {
			if a&x == 0 || b&y == 0 {
				continue
			}
			yes := x == predicateTrue || y == predicateTrue
			if and {
				yes = x == predicateTrue && y == predicateTrue
			}
			if yes {
				result |= predicateTrue
			} else {
				result |= predicateFalse
			}
		}
	}
	return result
}

func (v *predicateVerifier) expression(n *ast.Node, parameter *ast.Symbol, path predicatePath) (predicateTruth, error) {
	n = ast.SkipParentheses(n)
	switch n.Kind {
	case ast.KindTrueKeyword:
		return predicateTrue, nil
	case ast.KindFalseKeyword:
		return predicateFalse, nil
	case ast.KindIdentifier:
		if v.truthiness && v.sameParameter(n, parameter) {
			if v.cells[path.cell] == "truthy" {
				return predicateTrue, nil
			}
			return predicateFalse, nil
		}
		if value, ok := path.locals[v.l.checker.GetSymbolAtLocation(n)]; ok {
			return value, nil
		}
		return predicateEither, nil
	case ast.KindPrefixUnaryExpression:
		u := n.AsPrefixUnaryExpression()
		if u.Operator == ast.KindExclamationToken {
			t, err := v.expression(u.Operand, parameter, path)
			return predicateNot(t), err
		}
	case ast.KindBinaryExpression:
		b := n.AsBinaryExpression()
		if ast.IsAssignmentOperator(b.OperatorToken.Kind) {
			return 0, predicateFailure(v.l, n, "mutation invalidates the facts before this return path")
		}
		if b.OperatorToken.Kind == ast.KindAmpersandAmpersandToken || b.OperatorToken.Kind == ast.KindBarBarToken {
			a, err := v.expression(b.Left, parameter, path)
			if err != nil {
				return 0, err
			}
			z, err := v.expression(b.Right, parameter, path)
			if err != nil {
				return 0, err
			}
			return predicateCombine(a, z, b.OperatorToken.Kind == ast.KindAmpersandAmpersandToken), nil
		}
		if b.OperatorToken.Kind == ast.KindEqualsEqualsEqualsToken || b.OperatorToken.Kind == ast.KindExclamationEqualsEqualsToken {
			for _, pair := range [][2]*ast.Node{{b.Left, b.Right}, {b.Right, b.Left}} {
				test := ast.SkipParentheses(pair[0])
				constant := pair[1]
				matched := false
				yes := false
				if v.field == "" && test.Kind == ast.KindTypeOfExpression && v.sameParameter(test.AsTypeOfExpression().Expression, parameter) && constant.Kind == ast.KindStringLiteral {
					matched = true
					yes = v.cells[path.cell] == constant.Text()
				}
				if v.field != "" && test.Kind == ast.KindPropertyAccessExpression && test.Name().Text() == v.field && v.sameParameter(test.AsPropertyAccessExpression().Expression, parameter) {
					key, ok := predicateLiteral(v.l.checker.GetTypeAtLocation(constant))
					if ok && v.constant(constant) {
						matched = true
						yes = v.cells[path.cell] == key
					}
				}
				if matched {
					if b.OperatorToken.Kind == ast.KindExclamationEqualsEqualsToken {
						yes = !yes
					}
					if yes {
						return predicateTrue, nil
					}
					return predicateFalse, nil
				}
			}
		}
		// Pure comparisons outside the known partition provide no narrowing fact.
		if b.OperatorToken.Kind == ast.KindGreaterThanToken || b.OperatorToken.Kind == ast.KindLessThanToken {
			if v.pure(b.Left) && v.pure(b.Right) {
				return predicateEither, nil
			}
		}
	case ast.KindCallExpression:
		call := n.AsCallExpression()
		if len(call.Arguments.Nodes) != 1 || !v.sameParameter(call.Arguments.Nodes[0], parameter) || !ast.IsIdentifier(call.Expression) {
			break
		}
		symbol := v.l.symbol(call.Expression)
		if symbol != nil {
			for _, d := range symbol.Declarations {
				if values, ok := v.summaries[d]; ok {
					// This summary partitions the helper's predicate parameter,
					// not an arbitrary argument with the same caller symbol.
					claim := predicateOfSignature(v.l.checker, v.l.checker.GetSignatureFromDeclaration(d))
					if claim == nil || claim.ParameterIndex() != 0 {
						return 0, predicateFailure(v.l, n, "helper argument 0 does not occupy its predicate parameter; pass the tested value at the helper's predicate parameter index")
					}
					return values[path.cell], nil
				}
			}
		}
		return 0, predicateFailure(v.l, n, "unconverged or opaque helper on this return path")
	}
	return 0, predicateFailure(v.l, n, "opaque test or possible mutation on this return path")
}

func (v *predicateVerifier) sameParameter(n *ast.Node, parameter *ast.Symbol) bool {
	n = ast.SkipParentheses(n)
	return ast.IsIdentifier(n) && v.l.checker.GetSymbolAtLocation(n) == parameter
}

func (v *predicateVerifier) constant(n *ast.Node) bool {
	n = ast.SkipParentheses(n)
	switch n.Kind {
	case ast.KindStringLiteral, ast.KindNumericLiteral, ast.KindTrueKeyword, ast.KindFalseKeyword:
		return true
	case ast.KindPropertyAccessExpression:
		symbol := v.l.checker.GetSymbolAtLocation(n)
		return symbol != nil && (symbol.Flags&ast.SymbolFlagsEnumMember != 0 || v.l.checker.IsReadonlySymbol(symbol))
	}
	return false
}

func (v *predicateVerifier) pure(n *ast.Node) bool {
	n = ast.SkipParentheses(n)
	return n.Kind == ast.KindIdentifier || n.Kind == ast.KindNumericLiteral || n.Kind == ast.KindStringLiteral
}

func copyPredicatePath(path predicatePath) predicatePath {
	copy := predicatePath{cell: path.cell, locals: map[*ast.Symbol]predicateTruth{}}
	for symbol, value := range path.locals {
		copy.locals[symbol] = value
	}
	return copy
}

func (v *predicateVerifier) statements(nodes []*ast.Node, parameter *ast.Symbol, paths []predicatePath, check func(*ast.Node, predicateTruth) error) ([]predicatePath, error) {
	for _, n := range nodes {
		var next []predicatePath
		for _, path := range paths {
			switch n.Kind {
			case ast.KindBlock:
				result, err := v.statements(n.AsBlock().Statements.Nodes, parameter, []predicatePath{path}, check)
				if err != nil {
					return nil, err
				}
				next = append(next, result...)
			case ast.KindReturnStatement:
				result := predicateTrue
				if expression := n.AsReturnStatement().Expression; expression != nil {
					value, err := v.expression(expression, parameter, path)
					if err != nil {
						return nil, err
					}
					result = value
				}
				if err := check(n, result); err != nil {
					return nil, err
				}
			case ast.KindIfStatement:
				branch := n.AsIfStatement()
				condition, err := v.expression(branch.Expression, parameter, path)
				if err != nil {
					return nil, err
				}
				for _, side := range []struct {
					truth predicateTruth
					body  *ast.Node
				}{{predicateTrue, branch.ThenStatement}, {predicateFalse, branch.ElseStatement}} {
					if condition&side.truth == 0 {
						continue
					}
					p := copyPredicatePath(path)
					if side.body != nil && v.neverStatement(side.body, map[*ast.Node]bool{}) {
						continue
					}
					if side.body == nil {
						next = append(next, p)
						continue
					}
					result, err := v.statements([]*ast.Node{side.body}, parameter, []predicatePath{p}, check)
					if err != nil {
						return nil, err
					}
					next = append(next, result...)
				}
			case ast.KindVariableStatement:
				for _, d := range n.AsVariableStatement().DeclarationList.AsVariableDeclarationList().Declarations.Nodes {
					variable := d.AsVariableDeclaration()
					if !ast.IsIdentifier(d.Name()) || variable.Initializer == nil {
						return nil, predicateFailure(v.l, n, "an unproven alias on this return path")
					}
					value, err := v.expression(variable.Initializer, parameter, path)
					if err != nil {
						return nil, err
					}
					path.locals[v.l.checker.GetSymbolAtLocation(d.Name())] = value
				}
				next = append(next, path)
			case ast.KindExpressionStatement:
				expression := n.AsExpressionStatement().Expression
				if v.neverCall(expression, map[*ast.Node]bool{}) {
					continue
				}
				if v.l.isPanicCall(expression) {
					call := expression.AsCallExpression()
					for _, argument := range call.Arguments.Nodes {
						if !v.pure(argument) {
							return nil, predicateFailure(v.l, argument, "opaque panic argument may mutate this path")
						}
					}
					continue
				}
				if v.truthiness && expression.Kind == ast.KindCallExpression {
					return nil, predicateFailure(v.l, n, "a failure helper can return normally on this normal return path")
				}
				_, err := v.expression(expression, parameter, path)
				if err != nil {
					return nil, err
				}
				next = append(next, path)
			default:
				return nil, predicateFailure(v.l, n, "unsupported control flow or mutation on this return path")
			}
		}
		paths = next
	}
	return paths, nil
}

// An assertion on a condition has a truthiness postcondition, not a structural
// target. Partition all possible inputs into truthy and falsy values, rather
// than treating unknown as a boolean or trusting the asserts annotation.
func (l *lowering) proveConditionAssertion(node *ast.Node) (predicateProof, error) {
	declaration := node.Parent
	verifier := &predicateVerifier{l: l, truthiness: true, cells: []string{"truthy", "falsy"}}
	parameter := verifier.parameter(declaration)
	if parameter == nil || len(declaration.TypeParameters()) != 0 {
		return predicateProof{}, predicateFailure(l, node, "a non-parameter assertion has no truthiness proof")
	}
	for _, argument := range declaration.Parameters() {
		declared := argument.AsParameterDeclaration()
		if declared.Initializer != nil || declared.DotDotDotToken != nil || !ast.IsIdentifier(argument.Name()) {
			return predicateProof{}, predicateFailure(l, argument, "parameter initialization may change the asserted input")
		}
	}
	if declaration.Body().Kind != ast.KindBlock {
		return predicateProof{}, predicateFailure(l, node, "an assertion needs a proved normal return path")
	}
	for cell := range verifier.cells {
		check := func(returned *ast.Node, _ predicateTruth) error {
			if verifier.cells[cell] != "truthy" {
				return predicateFailure(l, returned, "normal return does not establish the asserted condition's truthiness")
			}
			return nil
		}
		paths, err := verifier.statements(declaration.Body().AsBlock().Statements.Nodes, parameter, []predicatePath{{cell: cell, locals: map[*ast.Symbol]predicateTruth{}}}, check)
		if err != nil {
			return predicateProof{}, err
		}
		if len(paths) != 0 {
			if err := check(declaration.Body(), predicateTrue); err != nil {
				return predicateProof{}, err
			}
		}
	}
	return predicateProof{}, nil
}

// A never annotation alone is not evidence. Inspect a direct implementation's
// exits; recursive or bodyless failure helpers have no termination summary.
func (v *predicateVerifier) neverCall(node *ast.Node, visiting map[*ast.Node]bool) bool {
	node = ast.SkipParentheses(node)
	if node.Kind != ast.KindCallExpression {
		return false
	}
	if v.l.isPanicCall(node) {
		return true
	}
	call := node.AsCallExpression()
	callee := ast.SkipParentheses(call.Expression)
	if !ast.IsIdentifier(callee) && callee.Kind != ast.KindPropertyAccessExpression {
		return false
	}
	symbol := v.l.symbol(callee)
	if symbol == nil {
		return false
	}
	for _, declaration := range symbol.Declarations {
		if !ast.IsFunctionLike(declaration) || declaration.Body() == nil || visiting[declaration] {
			continue
		}
		signature := v.l.checker.GetSignatureFromDeclaration(declaration)
		if signature == nil || v.l.checker.GetReturnTypeOfSignature(signature).Flags()&checker.TypeFlagsNever == 0 {
			continue
		}
		visiting[declaration] = true
		proved := v.neverStatement(declaration.Body(), visiting)
		delete(visiting, declaration)
		if proved {
			return true
		}
	}
	return false
}

func (v *predicateVerifier) neverStatement(node *ast.Node, visiting map[*ast.Node]bool) bool {
	switch node.Kind {
	case ast.KindThrowStatement:
		return true
	case ast.KindExpressionStatement:
		return v.neverCall(node.AsExpressionStatement().Expression, visiting)
	case ast.KindReturnStatement:
		expression := node.AsReturnStatement().Expression
		return expression != nil && v.neverCall(expression, visiting)
	case ast.KindIfStatement:
		branch := node.AsIfStatement()
		return branch.ElseStatement != nil && v.neverStatement(branch.ThenStatement, visiting) && v.neverStatement(branch.ElseStatement, visiting)
	case ast.KindBlock:
		for _, statement := range node.AsBlock().Statements.Nodes {
			if v.neverStatement(statement, visiting) {
				return true
			}
			if predicateNormalExit(statement) {
				return false
			}
		}
	}
	return false
}

// Untreated control flow may escape a block or override a pending throw.
// Ordinary statements before a terminal throw are harmless to non-return,
// even if they mutate state: they are never used as surviving narrowing facts.
func predicateNormalExit(node *ast.Node) bool {
	if ast.IsFunctionLike(node) {
		return false
	}
	switch node.Kind {
	case ast.KindReturnStatement, ast.KindBreakStatement, ast.KindContinueStatement, ast.KindTryStatement:
		return true
	}
	found := false
	node.ForEachChild(func(child *ast.Node) bool {
		if predicateNormalExit(child) {
			found = true
		}
		return found
	})
	return found
}

// Overloads share the implementation's control flow, under their admitted input.
// An annotation is never installed on the implementation as a checker fact.
func (l *lowering) predicateOverloadProven(implementation, overload *ast.Node) bool {
	outer := l.typeMapper
	defer func() { l.typeMapper = outer }()
	sources, targets := []*checker.Type{}, []*checker.Type{}
	for index, parameter := range implementation.TypeParameters() {
		if index >= len(overload.TypeParameters()) {
			return false
		}
		sources = append(sources, l.checker.GetTypeAtLocation(parameter.Name()))
		targets = append(targets, l.checker.GetTypeAtLocation(overload.TypeParameters()[index].Name()))
	}
	if len(sources) > 0 {
		l.typeMapper = newTypeMapper(sources, targets)
	}
	claim := predicateOfSignature(l.checker, l.checker.GetSignatureFromDeclaration(overload))
	if claim == nil || int(claim.ParameterIndex()) >= len(implementation.Parameters()) {
		return false
	}
	index := int(claim.ParameterIndex())
	if index < 0 {
		return false
	}
	parameter := implementation.Parameters()[index]
	if !ast.IsIdentifier(parameter.Name()) || parameter.AsParameterDeclaration().Initializer != nil || parameter.AsParameterDeclaration().DotDotDotToken != nil {
		return false
	}
	admitted, _, rest, err := l.censusOverloadParameter(overload.Parameters(), index)
	if err != nil || rest || admitted == nil {
		return false
	}
	changed := false
	var writes ast.Visitor
	writes = func(node *ast.Node) bool {
		if ast.IsIdentifier(node) && l.symbol(node) == l.symbol(parameter.Name()) && ast.IsAssignmentTarget(node) {
			changed = true
		}
		node.ForEachChild(writes)
		return false
	}
	implementation.Body().ForEachChild(writes)
	if changed {
		return false
	}
	target := claim.Type()
	if target == nil {
		if admitted.Flags()&checker.TypeFlagsBooleanLike == 0 {
			return false
		}
		target = predicateTrueType(l.checker)
	}
	proof := predicateFlowProof{l: l, function: implementation, parameter: parameter, declared: l.checker.GetTypeAtLocation(parameter.Name()), admitted: admitted, target: l.concrete(target), assertion: claim.Kind() == checker.TypePredicateKindAssertsIdentifier}
	return proof.proveBody(overload.Type()) == nil
}

// The existing overload-result seam supplies the call. A small IR wrapper keeps
// argument evaluation and the implementation call single, then checks both
// predicate directions against those arguments before the caller can narrow.
func (l *lowering) predicateOverloadResult(call *ast.CallExpression, value ir.Expression, implementation, overload *ast.Node) (ir.Expression, error) {
	// Until .a refusal mode exists, .a and .ts share the ruled call-site checks.
	directions := l.predicateUseDirections(call)
	proven := l.predicateOverloadProven(implementation, overload)
	l.recordPredicateChecks(call, implementation, overload, directions, proven)
	if proven {
		return value, nil
	}
	if directions == 0 {
		return value, nil
	}
	invoked, ok := value.(ir.Call)
	if !ok {
		return nil, l.notYet(call.AsNode(), "a checked predicate overload on an indirect call")
	}
	resolved := l.checker.GetResolvedSignature(call.AsNode())
	claim := predicateOfSignature(l.checker, resolved)
	if claim == nil {
		return nil, l.notYet(overload, "a predicate overload without a reifiable target")
	}
	assertion := claim.Kind() == checker.TypePredicateKindAssertsIdentifier
	if claim.Type() == nil && !assertion {
		return nil, l.notYet(overload, "a predicate overload without a reifiable target")
	}
	index := int(claim.ParameterIndex())
	if index < 0 || index >= len(invoked.Arguments) {
		return nil, l.notYet(overload, "a predicate overload on a missing argument")
	}
	if (!assertion && invoked.Type() != ir.Boolean) || (assertion && invoked.Type() != 0) {
		return nil, l.notYet(overload, "a checked predicate overload with a non-boolean result")
	}
	ordinal := l.predicateOverloadOrdinal(implementation, overload)
	message := fmt.Sprintf("overload %d of %s result: predicate %s is false", ordinal, implementation.Name().Text(), claim.ParameterName())
	wrapper := len(l.result.Functions)
	l.result.Functions = append(l.result.Functions, ir.Function{Name: fmt.Sprintf("%s_overload_%d_check_%d", implementation.Name().Text(), ordinal, wrapper), Returns: invoked.Type()})
	local := func(name string, of ir.Type) int {
		index := len(l.result.Locals)
		l.result.Locals = append(l.result.Locals, ir.Local{Name: name, Type: of, Function: wrapper})
		return index
	}
	arguments := []ir.Expression{}
	for index, argument := range invoked.Arguments {
		// Direct emission contextualizes undefined at the callee parameter.
		// Preserve that representation when passing through wrapper locals.
		if undefined, ok := argument.(ir.Undefined); ok && index < len(l.result.Functions[l.result.CallTargets(invoked)[0]].Parameters) {
			parameter := l.result.Functions[l.result.CallTargets(invoked)[0]].Parameters[index]
			undefined.Of = l.result.Locals[parameter].Type
			argument = undefined
			invoked.Arguments[index] = argument
		}
		parameter := local(fmt.Sprintf("argument_%d", index), argument.Type())
		l.result.Functions[wrapper].Parameters = append(l.result.Functions[wrapper].Parameters, parameter)
		arguments = append(arguments, ir.Read{Local: parameter, Of: argument.Type()})
	}
	checked := invoked
	checked.Arguments = arguments

	result := -1
	body := []ir.Statement{}
	if assertion {
		body = append(body, ir.Evaluate{Value: checked})
	} else {
		result = local("result", ir.Boolean)
		body = append(body, ir.Declare{Local: result, Value: checked})
	}
	source := l.checker.GetTypeOfSymbol(resolved.Parameters()[index])
	if _, undefined := invoked.Arguments[index].(ir.Undefined); undefined {
		source = l.checker.GetTypeAtLocation(call.Arguments.Nodes[index])
	}
	var setup []ir.Statement
	var membership ir.Expression
	var err error
	if claim.Type() == nil {
		membership = censusCondition(arguments[index])
	} else {
		setup, membership, err = l.predicateMembership(overload, arguments[index], source, claim.Type(), local, 0)
	}
	if err != nil {
		return nil, err
	}
	invalid := ir.Expression(ir.Unary{Operator: ir.Not, Operand: membership})
	var returned ir.Expression
	if !assertion {
		returned = ir.Read{Local: result, Of: ir.Boolean}
		invalid = predicateDirectionMismatch(returned, membership, directions)
	}
	checks := append(setup, ir.If{Condition: invalid, Then: []ir.Statement{ir.Panic{Message: ir.StringConstant{Index: l.constant(message)}}}})
	if !assertion && directions != predicateEither {
		observed := returned
		if directions == predicateFalse {
			observed = ir.Unary{Operator: ir.Not, Operand: returned}
		}
		// An erased direction must not execute target field or element reads.
		body = append(body, ir.If{Condition: observed, Then: checks})
	} else {
		body = append(body, checks...)
	}
	body = append(body, ir.Return{Value: returned})
	l.result.Functions[wrapper].Body = body

	return ir.Call{Function: wrapper, Arguments: invoked.Arguments, Returns: invoked.Type()}, nil
}

// Reification is limited to independently checkable contracts. Tagged interfaces
// continue through the shared view checker; untagged/callable contracts are not
// silently equated with a primitive typeof test.
func (l *lowering) predicateMembership(node *ast.Node, value ir.Expression, source, target *checker.Type, local func(string, ir.Type) int, depth int) ([]ir.Statement, ir.Expression, error) {
	target = l.concrete(target)
	source = l.concrete(source)
	if depth > 8 {
		return nil, nil, l.notYet(node, "a recursive predicate overload target")
	}
	equal := func(a, b ir.Expression) ir.Expression { return ir.Binary{Operator: ir.Equal, Left: a, Right: b} }
	isType := func(name string) ir.Expression {
		return equal(ir.TypeOf{Value: value}, ir.StringConstant{Index: l.constant(name)})
	}
	if target.Flags()&checker.TypeFlagsUnion != 0 {
		var setup []ir.Statement
		var result ir.Expression = ir.BooleanConstant{Value: false}
		for _, member := range target.Types() {
			statements, test, err := l.predicateMembership(node, value, source, member, local, depth+1)
			if err != nil {
				return nil, nil, err
			}
			setup = append(setup, statements...)
			result = ir.Binary{Operator: ir.Or, Left: result, Right: test}
		}
		return setup, result, nil
	}
	if target.Flags()&checker.TypeFlagsUndefined != 0 {
		return nil, isType("undefined"), nil
	}
	name := ""
	of := ir.Type(0)
	switch {
	case target.Flags()&checker.TypeFlagsStringLike != 0:
		name = "string"
		of = ir.String
	case target.Flags()&checker.TypeFlagsNumberLike != 0:
		name = "number"
		of = ir.Number
	case target.Flags()&checker.TypeFlagsBooleanLike != 0:
		name = "boolean"
		of = ir.Boolean
	}
	if name != "" {
		test := isType(name)
		if literal, _, ok := l.literalConstant(target); ok {
			narrowed := value
			if value.Type() == ir.Union {
				narrowed = ir.Narrow{Value: value, To: of}
			} else if value.Type().IsMaybe() {
				narrowed = ir.Unwrap{Value: value}
			}
			if narrowed.Type() != of {
				return nil, nil, l.notYet(node, "a predicate overload literal representation")
			}
			test = ir.Binary{Operator: ir.And, Left: test, Right: equal(narrowed, literal)}
		}
		return nil, test, nil
	}
	if l.checker.IsArrayType(target) && (source.Flags()&checker.TypeFlagsUndefined != 0 || value.Type() == ir.Number || value.Type() == ir.String || value.Type() == ir.Boolean) {
		return nil, ir.BooleanConstant{Value: false}, nil
	}
	if l.checker.IsArrayType(target) && value.Type() == ir.Array {
		arraySource := source
		if source.Flags()&checker.TypeFlagsUnion != 0 {
			arraySource = nil
			for _, member := range source.Types() {
				if l.checker.IsArrayType(member) {
					if arraySource != nil {
						return nil, nil, l.notYet(node, "a predicate overload over multiple array representations")
					}
					arraySource = member
				}
			}
		}
		if arraySource == nil || !l.checker.IsArrayType(arraySource) {
			return nil, nil, l.notYet(node, "a predicate overload without a known array representation")
		}
		element := l.checker.GetElementTypeOfArrayType(arraySource)
		// An identical element contract is already admitted on the source array.
		// The overload strengthens only presence, not its element view.
		if checker.Checker_isTypeIdenticalTo(l.checker, l.concrete(element), l.concrete(l.checker.GetElementTypeOfArrayType(target))) {
			return nil, censusCondition(value), nil
		}
		held, known := l.kept(element)
		if !known || slotless(held) {
			return nil, nil, l.notYet(node, "a checked predicate overload array element "+l.checker.TypeToString(element))
		}
		matches := local("array_matches", ir.Boolean)
		counter := local("array_index", ir.Number)
		read := ir.Read{Local: counter, Of: ir.Number}
		statements, test, err := l.predicateMembership(node, ir.ArrayIndex{Array: value, Index: read, Element: held}, element, l.checker.GetElementTypeOfArrayType(target), local, depth+1)
		if err != nil {
			return nil, nil, err
		}
		loopBody := append(statements, ir.If{Condition: ir.Unary{Operator: ir.Not, Operand: test}, Then: []ir.Statement{ir.Assign{Local: matches, Value: ir.BooleanConstant{Value: false}}, ir.Break{}}})
		setup := []ir.Statement{ir.Declare{Local: matches, Value: ir.BooleanConstant{Value: false}}, ir.If{Condition: censusCondition(value), Then: []ir.Statement{ir.Assign{Local: matches, Value: ir.BooleanConstant{Value: true}}, ir.Declare{Local: counter, Value: ir.NumberConstant{Value: 0}}, ir.Loop{Condition: ir.Binary{Operator: ir.Less, Left: read, Right: ir.Length{Array: value}}, Body: loopBody, Update: []ir.Statement{ir.Assign{Local: counter, Value: ir.Binary{Operator: ir.Add, Left: read, Right: ir.NumberConstant{Value: 1}}}}}}}}
		return setup, ir.Read{Local: matches, Of: ir.Boolean}, nil
	}
	if isClassInstance(target) && target.Symbol() != nil {
		for _, declaration := range target.Symbol().Declarations {
			if declaration.Kind != ast.KindClassDeclaration || len(declaration.TypeParameters()) != 0 {
				continue
			}
			if value.Type() != ir.Object && value.Type() != ir.Union {
				return nil, ir.BooleanConstant{Value: false}, nil
			}
			instance, err := l.instantiate(declaration, target, node)
			if err != nil {
				return nil, nil, err
			}
			object := value
			if value.Type() == ir.Union {
				object = ir.Narrow{Value: value, To: ir.Object}
			}
			return nil, ir.Binary{Operator: ir.And, Left: isType("object"), Right: ir.InstanceOf{Value: object, Class: instance.class}}, nil
		}
	}
	if target.Flags()&checker.TypeFlagsObject != 0 && !isClassInstance(target) && value.Type() == ir.Object {
		tag := l.fieldLiteral(target, "kind")
		if tag != nil {
			if _, err := l.view(node, nil, target); err != nil {
				return nil, nil, err
			}
			literal, of, known := l.literalConstant(tag)
			if known {
				return nil, ir.Binary{Operator: ir.And, Left: censusCondition(value), Right: equal(ir.Property{Object: value, Name: "kind", Of: of, View: "predicate argument.kind", ViewType: l.checker.TypeToString(tag)}, literal)}, nil
			}
		}
	}
	return nil, nil, l.notYet(node, "checked predicate overload target "+l.checker.TypeToString(target))
}

// A direction is observable whenever the checker still narrows a value read in
// its flow region. This includes aliases of the boolean result and continuation
// flows after return/throw; lexical then/else scanning would miss those reads.
func (l *lowering) predicateUseDirections(call *ast.CallExpression) predicateTruth {
	claim := predicateOfSignature(l.checker, l.checker.GetResolvedSignature(call.AsNode()))
	if claim == nil || int(claim.ParameterIndex()) < 0 || int(claim.ParameterIndex()) >= len(call.Arguments.Nodes) {
		return predicateEither
	}
	argument := ast.SkipParentheses(call.Arguments.Nodes[claim.ParameterIndex()])
	references := []*ast.Node{argument}
	for container := argument; container.Flags&ast.NodeFlagsOptionalChain != 0; {
		switch container.Kind {
		case ast.KindPropertyAccessExpression:
			container = ast.SkipParentheses(container.AsPropertyAccessExpression().Expression)
		case ast.KindElementAccessExpression:
			container = ast.SkipParentheses(container.AsElementAccessExpression().Expression)
		default:
			container = nil
		}
		if container == nil {
			break
		}
		references = append(references, container)
	}
	var directions predicateTruth
	for _, argument := range references {
		directions |= l.predicateReferenceDirections(call, argument)
	}
	return directions
}

func (l *lowering) predicateReferenceDirections(call *ast.CallExpression, argument *ast.Node) predicateTruth {
	if argument.Kind != ast.KindIdentifier && argument.Kind != ast.KindPropertyAccessExpression && argument.Kind != ast.KindElementAccessExpression && argument.Kind != ast.KindThisKeyword {
		// Temporary values cannot be narrowed by a later reference read.
		return 0
	}
	declared := l.checker.GetTypeAtLocation(argument)
	if argument.Kind == ast.KindIdentifier {
		declared = l.checker.GetTypeOfSymbol(l.symbol(argument))
	}
	var directions predicateTruth
	var visit ast.Visitor
	visit = func(node *ast.Node) bool {
		if l.predicateSameReference(node, argument) && !ast.IsDeclarationName(node) && !predicateWriteOnly(node) && !ast.IsPartOfTypeNode(node) {
			actual := l.checker.GetTypeAtLocation(node)
			if !checker.Checker_isTypeIdenticalTo(l.checker, actual, declared) {
				if flow := node.FlowNodeData(); flow != nil {
					candidates := l.predicateFlowDirections(flow.FlowNode, call.AsNode(), argument, map[*ast.FlowNode]bool{})
					for _, direction := range []predicateTruth{predicateTrue, predicateFalse} {
						if candidates&direction == 0 {
							continue
						}
						without := l.predicateFlowWithout(flow.FlowNode, call.AsNode(), node, direction)
						unclaimed := predicateFlowType(l.checker, node, declared, declared, nil, without)
						if !checker.Checker_isTypeIdenticalTo(l.checker, actual, unclaimed) {
							directions |= direction
						}
					}
				}
			}
		}
		node.ForEachChild(visit)
		return false
	}
	for _, file := range l.program.Files() {
		file.AsNode().ForEachChild(visit)
	}
	return directions
}

func (l *lowering) predicateSameReference(a, b *ast.Node) bool {
	return a != nil && b != nil && predicateMatchingReference(l.checker, b, a)
}

// Follow the checker's existing graph rather than inventing branch regions.
func (l *lowering) predicateFlowDirections(flow *ast.FlowNode, call, reference *ast.Node, seen map[*ast.FlowNode]bool) predicateTruth {
	if flow == nil || seen[flow] {
		return 0
	}
	seen[flow] = true
	// A replacement kills earlier predicate facts for this reference. Compound
	// assignments also read the old narrowed value and must keep those checks.
	if flow.Flags&ast.FlowFlagsAssignment != 0 && l.predicateSameReference(flow.Node, reference) && predicateWriteOnly(flow.Node) {
		return 0
	}
	var result predicateTruth
	if flow.Flags&ast.FlowFlagsCondition != 0 {
		truth := flow.Flags&ast.FlowFlagsTrueCondition != 0
		result |= l.predicateConditionDirection(flow.Node, call, truth, 0)
	}
	if flow.Flags&ast.FlowFlagsCall != 0 && flow.Node == call {
		result |= predicateTrue
	}
	result |= l.predicateFlowDirections(flow.Antecedent, call, reference, seen)
	for list := flow.Antecedents; list != nil; list = list.Next {
		result |= l.predicateFlowDirections(list.Flow, call, reference, seen)
	}
	if flow.Flags&ast.FlowFlagsStart != 0 && flow.Node != nil {
		if outer := flow.Node.FlowNodeData(); outer != nil {
			result |= l.predicateFlowDirections(outer.FlowNode, call, reference, seen)
		}
	}
	return result
}

func (l *lowering) predicateConditionDirection(node, call *ast.Node, truth bool, depth int) predicateTruth {
	if node == nil || depth > 16 {
		return 0
	}
	node = ast.SkipParentheses(node)
	if node == call {
		if truth {
			return predicateTrue
		}
		return predicateFalse
	}
	if node.Kind == ast.KindPrefixUnaryExpression && node.AsPrefixUnaryExpression().Operator == ast.KindExclamationToken {
		return l.predicateConditionDirection(node.AsPrefixUnaryExpression().Operand, call, !truth, depth+1)
	}
	if node.Kind == ast.KindBinaryExpression {
		binary := node.AsBinaryExpression()
		switch binary.OperatorToken.Kind {
		case ast.KindAmpersandAmpersandToken, ast.KindBarBarToken:
			precise := truth == (binary.OperatorToken.Kind == ast.KindAmpersandAmpersandToken)
			if precise {
				return l.predicateConditionDirection(binary.Left, call, truth, depth+1) | l.predicateConditionDirection(binary.Right, call, truth, depth+1)
			}
			return l.predicateConditionDirection(binary.Left, call, true, depth+1) | l.predicateConditionDirection(binary.Left, call, false, depth+1) | l.predicateConditionDirection(binary.Right, call, true, depth+1) | l.predicateConditionDirection(binary.Right, call, false, depth+1)
		case ast.KindEqualsToken:
			return l.predicateConditionDirection(binary.Right, call, truth, depth+1)
		}
	}
	if node.Kind == ast.KindNonNullExpression || node.Kind == ast.KindSatisfiesExpression {
		return l.predicateConditionDirection(node.Expression(), call, truth, depth+1)
	}
	if node.Kind == ast.KindIdentifier {
		if symbol := l.symbol(node); symbol != nil {
			for _, declaration := range symbol.Declarations {
				if declaration.Kind == ast.KindVariableDeclaration && declaration.Parent.Flags&ast.NodeFlagsConst != 0 {
					return l.predicateConditionDirection(declaration.AsVariableDeclaration().Initializer, call, truth, depth+1)
				}
			}
		}
	}
	return 0
}

func (l *lowering) predicateDirectionCount(call *ast.CallExpression, directions predicateTruth) int {
	claim := predicateOfSignature(l.checker, l.checker.GetResolvedSignature(call.AsNode()))
	if claim != nil && claim.Kind() == checker.TypePredicateKindAssertsIdentifier {
		directions &= predicateTrue
	}
	count := 0
	if directions&predicateTrue != 0 {
		count++
	}
	if directions&predicateFalse != 0 {
		count++
	}
	return count
}

func predicateDirectionMismatch(returned, membership ir.Expression, directions predicateTruth) ir.Expression {
	mismatch := ir.Expression(ir.Binary{Operator: ir.NotEqual, Left: returned, Right: membership})
	if directions == predicateTrue {
		return ir.Binary{Operator: ir.And, Left: returned, Right: mismatch}
	}
	if directions == predicateFalse {
		return ir.Binary{Operator: ir.And, Left: ir.Unary{Operator: ir.Not, Operand: returned}, Right: mismatch}
	}
	return mismatch
}

func predicateWriteOnly(node *ast.Node) bool {
	if node == nil || !ast.IsAssignmentTarget(node) {
		return false
	}
	parent := node.Parent
	for parent != nil && parent.Kind == ast.KindParenthesizedExpression {
		parent = parent.Parent
	}
	return parent != nil && parent.Kind == ast.KindBinaryExpression && parent.AsBinaryExpression().OperatorToken.Kind == ast.KindEqualsToken
}

// Recompute the read with this call's directional fact removed. Merely finding
// an ancestor condition would attribute a later, independent guard's narrowing
// to every earlier call, even after their branches have rejoined.
// Fresh flow nodes keep the pinned checker's cache and original graph untouched.
func (l *lowering) predicateFlowWithout(root *ast.FlowNode, call, reference *ast.Node, direction predicateTruth) *ast.FlowNode {
	memo := map[*ast.FlowNode]*ast.FlowNode{}
	var clone func(*ast.FlowNode) *ast.FlowNode
	var list func(*ast.FlowList) *ast.FlowList
	list = func(original *ast.FlowList) *ast.FlowList {
		if original == nil {
			return nil
		}
		return &ast.FlowList{Flow: clone(original.Flow), Next: list(original.Next)}
	}
	clone = func(original *ast.FlowNode) *ast.FlowNode {
		if original == nil {
			return nil
		}
		if previous := memo[original]; previous != nil {
			return previous
		}
		copy := &ast.FlowNode{Flags: original.Flags &^ (ast.FlowFlagsShared | ast.FlowFlagsReferenced), Node: original.Node}
		memo[original] = copy
		remove := original.Flags&ast.FlowFlagsCall != 0 && original.Node == call && direction == predicateTrue
		if original.Flags&ast.FlowFlagsCondition != 0 {
			truth := original.Flags&ast.FlowFlagsTrueCondition != 0
			remove = l.predicateConditionDirection(original.Node, call, truth, 0)&direction != 0
		}
		if remove {
			copy.Flags, copy.Node = ast.FlowFlagsBranchLabel, nil
			copy.Antecedents = &ast.FlowList{Flow: clone(original.Antecedent)}
			return copy
		}
		copy.Antecedent, copy.Antecedents = clone(original.Antecedent), list(original.Antecedents)
		if original.Flags&ast.FlowFlagsStart != 0 && original.Node != nil && original.Node.FlowNodeData() != nil && original.Node.FlowNodeData().FlowNode != nil {
			// Stable identifier captures inherit the container's flow. Reconstruct
			// that edge explicitly, without altering its shared AST flow node.
			if reference.Kind == ast.KindIdentifier || (reference.Kind == ast.KindThisKeyword && ast.IsArrowFunction(original.Node)) {
				copy.Flags, copy.Node = ast.FlowFlagsBranchLabel, nil
				copy.Antecedents = &ast.FlowList{Flow: clone(original.Node.FlowNodeData().FlowNode)}
			}
		}
		if original.Flags&ast.FlowFlagsReduceLabel != 0 {
			data := original.Node.AsFlowReduceLabelData()
			copy.Node = ast.NewFlowReduceLabelData(clone(data.Target), list(data.Antecedents))
		}
		return copy
	}
	return clone(root)
}

func (l *lowering) predicateOverloadOrdinal(implementation, overload *ast.Node) int {
	ordinal := 0
	for _, declaration := range l.symbol(implementation.Name()).Declarations {
		if declaration.Kind == ast.KindFunctionDeclaration && declaration.Body() == nil {
			ordinal++
			if declaration == overload {
				return ordinal
			}
		}
	}
	return ordinal
}

func (l *lowering) recordPredicateChecks(call *ast.CallExpression, implementation, overload *ast.Node, observed predicateTruth, proven bool) {
	counts := &l.result.PredicateChecks
	site := ir.PredicateCallCheck{Where: l.program.Where(call.AsNode()), Function: implementation.Name().Text(), Overload: l.predicateOverloadOrdinal(implementation, overload)}
	for _, direction := range []predicateTruth{predicateTrue, predicateFalse} {
		if l.predicateDirectionCount(call, direction) == 0 {
			continue
		}
		name := "true"
		if direction == predicateFalse {
			name = "false"
		}
		report := ir.PredicateDirectionCheck{Direction: name}
		switch {
		case proven:
			report.Status, report.Reason = "proven", "implementation body proves this direction"
			counts.Proven++
		case observed&direction != 0:
			report.Status, report.Reason = "checked", "a narrowed read consumes this direction"
			counts.Checked++
		default:
			report.Status, report.Reason = "unobservable", "no narrowed read in the "+name+" region"
			counts.Proven++
			counts.Unobservable++
		}
		site.Directions = append(site.Directions, report)
	}
	counts.Sites = append(counts.Sites, site)
}

// Inferred callback predicates are claims too. Independently prove the resolved
// target from their own body; checker inference alone is not admission evidence.
func (l *lowering) proveInferredPredicate(function *ast.Node, target *checker.Type) bool {
	claim := predicateOfSignature(l.checker, l.checker.GetSignatureFromDeclaration(function))
	if claim == nil || claim.Type() == nil || !checker.Checker_isTypeIdenticalTo(l.checker, claim.Type(), target) {
		return false
	}
	index := int(claim.ParameterIndex())
	if index < 0 || index >= len(function.Parameters()) {
		return false
	}
	parameter := function.Parameters()[index]
	if parameter.Name().Kind != ast.KindIdentifier || parameter.AsParameterDeclaration().Initializer != nil || parameter.AsParameterDeclaration().DotDotDotToken != nil {
		return false
	}
	changed := false
	var writes ast.Visitor
	writes = func(node *ast.Node) bool {
		if node.Kind == ast.KindIdentifier && l.symbol(node) == l.symbol(parameter.Name()) && ast.IsAssignmentTarget(node) {
			changed = true
		}
		node.ForEachChild(writes)
		return false
	}
	function.Body().ForEachChild(writes)
	if changed {
		return false
	}
	proof := predicateFlowProof{l: l, function: function, parameter: parameter, declared: l.checker.GetTypeAtLocation(parameter.Name()), target: target}
	return proof.proveBody(function) == nil
}

internal/lower/predicates.go:
package lower

import (
	"fmt"
	_ "unsafe"

	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/microsoft/TypeScript/tsc/shim/scanner"
)

// As in instantiate.go, this calls the pinned checker's own implementation until its shim
// exports it. The annotation is a claimed postcondition, never a flow fact. The flow nodes below contain
// only checks independently trusted by Adamic, not assertion calls or assignments.
//
//go:linkname predicateFlowType github.com/microsoft/TypeScript/tsc/internal/checker.(*Checker).getFlowTypeOfReferenceEx
func predicateFlowType(receiver *checker.Checker, reference *ast.Node, declared, initial *checker.Type, container *ast.Node, flow *ast.FlowNode) *checker.Type

type predicateFlowProof struct {
	l          *lowering
	function   *ast.Node
	parameter  *ast.Node
	declared   *checker.Type
	admitted   *checker.Type
	target     *checker.Type
	assertion  bool
	trueTypes  []*checker.Type
	lastReturn *ast.Node
}

type predicateFlowPath struct {
	flow    *ast.FlowNode
	checked bool
}

func (p *predicateFlowProof) refused(node *ast.Node, reason string) error {
	return &Refused{Where: p.l.program.Where(node), What: "a type predicate whose return is not proven (" + reason + ")", Fix: "inline the check where you use it, or return a discriminant comparison on the unmodified parameter (adamic/no-type-predicate)"}
}

func (l *lowering) proveFlowPredicate(node *ast.Node) error {
	if l.censusPredicateMarkerContract(node) {
		return nil
	}
	annotation := node.AsTypePredicateNode()
	function := node.Parent
	if !ast.IsFunctionLike(function) || function.Body() == nil || annotation.ParameterName.Kind != ast.KindIdentifier {
		return (&predicateFlowProof{l: l}).refused(node, "there is no body proving this parameter")
	}
	var parameter *ast.Node
	for _, candidate := range function.Parameters() {
		if ast.IsIdentifier(candidate.Name()) && candidate.Name().Text() == annotation.ParameterName.Text() {
			parameter = candidate
			break
		}
	}
	p := &predicateFlowProof{l: l, function: function, parameter: parameter, assertion: annotation.AssertsModifier != nil}
	if parameter == nil || parameter.AsParameterDeclaration().Initializer != nil || parameter.AsParameterDeclaration().DotDotDotToken != nil {
		return p.refused(node, "the predicate must name an unchanged plain parameter")
	}
	p.declared = l.checker.GetTypeAtLocation(parameter.Name())
	if annotation.Type != nil {
		p.target = l.checker.GetTypeFromTypeNode(annotation.Type)
	} else {
		// asserts cond is accepted only for a boolean parameter, with a proven true postcondition.
		if p.declared.Flags()&checker.TypeFlagsBooleanLike == 0 {
			return p.refused(node, "asserts cond needs a boolean parameter")
		}
		p.target = predicateTrueType(l.checker)
	}
	// A rebinding changes the value being tested, not the caller's argument. Include writes in
	// nested closures, even if the checker happens to retain a narrowing across their calls.
	var changed *ast.Node
	var visit ast.Visitor
	visit = func(current *ast.Node) bool {
		if current.Kind == ast.KindIdentifier && l.checker.GetSymbolAtLocation(current) == l.checker.GetSymbolAtLocation(parameter.Name()) && ast.IsAssignmentTarget(current) {
			changed = current
		}
		current.ForEachChild(visit)
		return false
	}
	function.Body().ForEachChild(visit)
	if changed != nil {
		return p.refused(changed, "the predicate parameter is assigned")
	}
	return p.proveBody(node)
}

func (p *predicateFlowProof) proveBody(node *ast.Node) error {
	function := p.function
	paths := []predicateFlowPath{{flow: &ast.FlowNode{Flags: ast.FlowFlagsStart}}}
	var remaining []predicateFlowPath
	var err error
	if function.Body().Kind == ast.KindBlock {
		remaining, err = p.statement(function.Body(), paths)
	} else {
		err = p.returned(function.Body(), function.Body(), paths)
	}
	if err != nil {
		return err
	}
	for _, path := range remaining {
		if !p.assertion {
			return p.refused(function.Body(), "implicit return is not a proven boolean")
		}
		if err := p.normalReturn(function.Body(), path); err != nil {
			return err
		}
	}
	if !p.assertion && len(p.trueTypes) > 0 && !checker.Checker_isTypeIdenticalTo(p.l.checker, p.l.checker.GetUnionType(p.trueTypes), p.target) {
		return p.refused(p.lastReturn, "the body's true narrowing does not match "+p.l.checker.TypeToString(p.target))
	}
	return nil
}

func (p *predicateFlowProof) narrowed(path predicateFlowPath, initial *checker.Type) *checker.Type {
	if path.flow.Node != nil && p.l.isArrayPredicateCall(path.flow.Node) && p.reference(ast.SkipParentheses(ast.SkipParentheses(path.flow.Node).AsCallExpression().Arguments.Nodes[0])) {
		return p.l.arrayPredicateMembers(initial, path.flow.Flags&ast.FlowFlagsTrueCondition != 0)
	}
	if p.admitted != nil && initial == p.declared {
		initial = p.admitted
	}
	return p.l.concrete(predicateFlowType(p.l.checker, p.parameter.Name(), p.declared, initial, p.function, path.flow))
}

func predicateBranch(path predicateFlowPath, expression *ast.Node, truth bool) predicateFlowPath {
	flags := ast.FlowFlagsFalseCondition
	if truth {
		flags = ast.FlowFlagsTrueCondition
	}
	return predicateFlowPath{flow: &ast.FlowNode{Flags: flags, Node: expression, Antecedent: path.flow}, checked: true}
}

// Immutable scalar arguments carry their admitted value type into the body.
// An object view does not certify its current tag without an actual test.
func (p *predicateFlowProof) admittedValueProof() bool {
	return p.admitted != nil && p.target.Flags()&(checker.TypeFlagsNumberLike|checker.TypeFlagsStringLike|checker.TypeFlagsBooleanLike|checker.TypeFlagsUndefined) != 0
}

func (p *predicateFlowProof) normalReturn(node *ast.Node, path predicateFlowPath) error {
	narrowed := p.narrowed(path, p.declared)
	if (!path.checked && !p.admittedValueProof()) || !checker.Checker_isTypeIdenticalTo(p.l.checker, narrowed, p.target) || p.l.nominalMismatch(narrowed, p.target, map[[2]*checker.Type]bool{}) != nil {
		return p.refused(node, "normal return has not narrowed "+p.parameter.Name().Text()+" to "+p.l.checker.TypeToString(p.target))
	}
	return nil
}

func (p *predicateFlowProof) returned(node, expression *ast.Node, paths []predicateFlowPath) error {
	p.lastReturn = node
	if p.assertion {
		if expression != nil {
			return p.refused(node, "an assertion must return without a value")
		}
		for _, path := range paths {
			if err := p.normalReturn(node, path); err != nil {
				return err
			}
		}
		return nil
	}
	if expression == nil {
		return p.refused(node, "return has no boolean check")
	}
	expression = ast.SkipParentheses(expression)
	literal := expression.Kind == ast.KindTrueKeyword || expression.Kind == ast.KindFalseKeyword
	if !literal && !p.check(expression) {
		return p.refused(node, "return expression is not a trusted check on "+p.parameter.Name().Text())
	}
	for _, path := range paths {
		for _, truth := range []bool{true, false} {
			if literal && truth != (expression.Kind == ast.KindTrueKeyword) {
				continue
			}
			branch := path
			if !literal {
				branch = predicateBranch(path, expression, truth)
			}
			// For a false path, an argument initially in the claimed type must be
			// impossible, as for inferred predicates. That proves the caller's else
			// narrowing independently of the true-return comparison.
			if truth {
				narrowed := p.narrowed(branch, p.declared)
				if (!branch.checked && !p.admittedValueProof()) || !p.l.checker.IsTypeAssignableTo(narrowed, p.target) || p.l.nominalMismatch(narrowed, p.target, map[[2]*checker.Type]bool{}) != nil {
					return p.refused(node, "true return narrows to "+p.l.checker.TypeToString(narrowed)+", not "+p.l.checker.TypeToString(p.target))
				}
				p.trueTypes = append(p.trueTypes, narrowed)
			} else if p.narrowed(branch, p.target).Flags()&checker.TypeFlagsNever == 0 {
				return p.refused(node, "false return can still contain "+p.l.checker.TypeToString(p.target))
			}
		}
	}
	return nil
}

func (p *predicateFlowProof) statement(node *ast.Node, paths []predicateFlowPath) ([]predicateFlowPath, error) {
	if len(paths) == 0 {
		return nil, nil
	}
	if len(paths) > 256 {
		return nil, p.refused(node, "too many return paths to prove")
	}
	switch node.Kind {
	case ast.KindBlock:
		for _, statement := range node.AsBlock().Statements.Nodes {
			var err error
			paths, err = p.statement(statement, paths)
			if err != nil {
				return nil, err
			}
		}
		return paths, nil
	case ast.KindIfStatement:
		statement := node.AsIfStatement()
		if !p.check(statement.Expression) {
			return nil, p.refused(node, "branch is not a trusted parameter check")
		}
		var then, otherwise []predicateFlowPath
		for _, path := range paths {
			then = append(then, predicateBranch(path, statement.Expression, true))
			otherwise = append(otherwise, predicateBranch(path, statement.Expression, false))
		}
		then, err := p.statement(statement.ThenStatement, then)
		if err != nil {
			return nil, err
		}
		if statement.ElseStatement != nil {
			otherwise, err = p.statement(statement.ElseStatement, otherwise)
			if err != nil {
				return nil, err
			}
		}
		return append(then, otherwise...), nil
	case ast.KindReturnStatement:
		return nil, p.returned(node, node.AsReturnStatement().Expression, paths)
	case ast.KindThrowStatement:
		return nil, nil
	case ast.KindEmptyStatement:
		return paths, nil
	case ast.KindExpressionStatement, ast.KindVariableStatement:
		if node.Kind == ast.KindExpressionStatement && p.l.isPanicCall(node.Expression()) {
			return nil, nil
		}
		if predicateEffects(node) {
			// Unknown calls and all writes can invalidate discriminants through an alias. Starting
			// over also prevents the checker from retaining stale readonly-property facts.
			for index := range paths {
				paths[index] = predicateFlowPath{flow: &ast.FlowNode{Flags: ast.FlowFlagsStart}}
			}
		}
		return paths, nil
	default:
		return nil, p.refused(node, fmt.Sprintf("return paths through %s are not verified", node.Kind))
	}
}

// check recognizes only independently trusted narrowing expressions, with no calls, aliases,
// casts or computed property accesses. The checker still decides what each branch proves.
func (p *predicateFlowProof) check(node *ast.Node) bool {
	node = ast.SkipParentheses(node)
	if node.Kind == ast.KindPrefixUnaryExpression && node.AsPrefixUnaryExpression().Operator == ast.KindExclamationToken {
		return p.check(node.AsPrefixUnaryExpression().Operand)
	}
	if p.assertion && p.target == predicateTrueType(p.l.checker) && p.reference(node) {
		return true
	}
	if p.l.isArrayPredicateCall(node) {
		return p.reference(ast.SkipParentheses(node.AsCallExpression().Arguments.Nodes[0])) && (p.l.arrayPredicateDomain(p.declared) || p.declared.Flags()&checker.TypeFlagsUnknown != 0)
	}
	if node.Kind != ast.KindBinaryExpression {
		return false
	}
	binary := node.AsBinaryExpression()
	switch binary.OperatorToken.Kind {
	case ast.KindAmpersandAmpersandToken, ast.KindBarBarToken:
		return p.check(binary.Left) && p.check(binary.Right)
	case ast.KindInstanceOfKeyword:
		if !p.reference(ast.SkipParentheses(binary.Left)) || binary.Right.Kind != ast.KindIdentifier {
			return false
		}
		symbol := p.l.checker.GetSymbolAtLocation(binary.Right)
		if symbol != nil && symbol.Flags&ast.SymbolFlagsAlias != 0 {
			symbol = p.l.checker.GetAliasedSymbol(symbol)
		}
		return symbol != nil && symbol.Flags&ast.SymbolFlagsClass != 0
	case ast.KindEqualsEqualsEqualsToken, ast.KindExclamationEqualsEqualsToken:
		return p.checkedValue(binary.Left) && p.literal(binary.Right) || p.checkedValue(binary.Right) && p.literal(binary.Left)
	}
	return false
}

func (p *predicateFlowProof) reference(node *ast.Node) bool {
	return node.Kind == ast.KindIdentifier && p.l.checker.GetSymbolAtLocation(node) == p.l.checker.GetSymbolAtLocation(p.parameter.Name())
}

func (p *predicateFlowProof) checkedValue(node *ast.Node) bool {
	node = ast.SkipParentheses(node)
	if p.reference(node) {
		return true
	}
	if node.Kind == ast.KindTypeOfExpression {
		return p.reference(ast.SkipParentheses(node.AsTypeOfExpression().Expression))
	}
	return node.Kind == ast.KindPropertyAccessExpression && p.reference(ast.SkipParentheses(node.AsPropertyAccessExpression().Expression)) && node.Flags&ast.NodeFlagsOptionalChain == 0
}

func (p *predicateFlowProof) literal(node *ast.Node) bool {
	node = ast.SkipParentheses(node)
	switch node.Kind {
	case ast.KindStringLiteral, ast.KindNumericLiteral, ast.KindNullKeyword, ast.KindTrueKeyword, ast.KindFalseKeyword:
		return true
	case ast.KindIdentifier:
		return node.Text() == "undefined" && p.l.checker.GetSymbolAtLocation(node) == p.l.checker.GetUndefinedSymbol()
	}
	return false
}

func predicateEffects(node *ast.Node) bool {
	switch node.Kind {
	case ast.KindPropertyAccessExpression, ast.KindElementAccessExpression:
		// A property read may dispatch a getter through a structural view.
		return true
	case ast.KindCallExpression, ast.KindNewExpression, ast.KindBinaryExpression:
		if node.Kind != ast.KindBinaryExpression || ast.IsAssignmentOperator(node.AsBinaryExpression().OperatorToken.Kind) {
			return true
		}
	case ast.KindPostfixUnaryExpression, ast.KindFunctionDeclaration, ast.KindFunctionExpression, ast.KindArrowFunction:
		return true
	case ast.KindPrefixUnaryExpression:
		operator := node.AsPrefixUnaryExpression().Operator
		if operator == ast.KindPlusPlusToken || operator == ast.KindMinusMinusToken {
			return true
		}
	}
	return node.ForEachChild(predicateEffects)
}

func predicateTrueType(c *checker.Checker) *checker.Type {
	for _, member := range c.GetBooleanType().Types() {
		if member.AsLiteralType().Value() == true {
			return member
		}
	}
	panic("checker boolean type has no true member")
}

// The flow verifier keeps main's literal and nominal proofs. Body summaries add
// verified helpers and truthiness assertions; tag-only facts use checked views.
func (l *lowering) predicateRefusal(node *ast.Node) error {
	if node.Parent.Kind == ast.KindFunctionDeclaration && node.Parent.Body() == nil && l.censusImplementation(node.Parent) != nil {
		// TODO: .a refusal mode must prove the overload through its implementation
		// here and refuse an over-promising declaration. .ts keeps call-site checks.
		return nil
	}
	if l.predicateParameter(node) != nil {
		return nil
	}
	original := l.proveFlowPredicate(node)
	if original == nil {
		return nil
	}
	proof, err := l.provePredicate(node)
	if err != nil {
		return original
	}
	if proof.TaggedView {
		target := l.checker.GetTypeAtLocation(node.AsTypePredicateNode().Type)
		members := []*checker.Type{target}
		if target.Flags()&checker.TypeFlagsUnion != 0 {
			members = target.Types()
		}
		for _, member := range members {
			for _, property := range l.checker.GetPropertiesOfType(member) {
				if property.Flags&ast.SymbolFlagsOptional != 0 {
					return original
				}
			}
			if _, err := l.view(node, nil, member); err != nil {
				return err
			}
		}
	}
	return nil
}

// A signature on a plain function parameter is an argument contract. The call
// visitor proves the actual function body before admitting any invocation. Live
// contracts also need a closed set of direct callers; an uncalled declaration or
// an escaped function value supplies no producer proof for its callback.
func (l *lowering) predicateParameter(node *ast.Node) *ast.Node {
	signature := node.Parent
	if signature == nil || signature.Kind != ast.KindFunctionType || signature.Parent == nil || signature.Parent.Kind != ast.KindParameter {
		return nil
	}
	parameter := signature.Parent
	if parameter.AsParameterDeclaration().Initializer != nil || parameter.AsParameterDeclaration().DotDotDotToken != nil {
		return nil
	}
	function := parameter.Parent
	if function.Kind == ast.KindFunctionDeclaration && function.Body() == nil {
		implementation := l.censusImplementation(function)
		if implementation == nil {
			return nil
		}
		for index, candidate := range function.Parameters() {
			if candidate == parameter && index < len(implementation.Parameters()) {
				parameter = implementation.Parameters()[index]
				function = implementation
				break
			}
		}
	}
	if !ast.IsFunctionLike(function) || function.Body() == nil {
		return nil
	}
	symbol := l.checker.GetSymbolAtLocation(parameter.Name())
	changed := false
	var visit ast.Visitor
	visit = func(n *ast.Node) bool {
		if n.Kind == ast.KindIdentifier && l.checker.GetSymbolAtLocation(n) == symbol && ast.IsAssignmentTarget(n) {
			changed = true
		}
		n.ForEachChild(visit)
		return false
	}
	function.Body().ForEachChild(visit)
	if changed {
		return nil
	}
	// A bodyless overload's callback predicate is not the implementation's
	// contract when the implementation takes an ordinary boolean callback.
	if signature.Parent != parameter && parameter.Type() != nil && parameter.Type().Kind == ast.KindFunctionType && parameter.Type().Type() != nil && parameter.Type().Type().Kind != ast.KindTypePredicate {
		return parameter
	}
	if !l.predicateCallbackCallers(function, symbol) {
		return nil
	}
	return parameter
}

// Every producer is checked by predicateArguments before annotations are admitted.
// Keep that proof within direct calls, and do not let a callback escape its body.
func (l *lowering) predicateCallbackCallers(function *ast.Node, callback *ast.Symbol) bool {
	if function.Kind != ast.KindFunctionDeclaration || !ast.IsIdentifier(function.Name()) || ast.HasSyntacticModifier(function, ast.ModifierFlagsExport) {
		return false
	}
	owner := l.symbol(function.Name())
	if owner == nil {
		return false
	}
	found, safe := false, true
	var visit ast.Visitor
	visit = func(node *ast.Node) bool {
		if ast.IsIdentifier(node) && !ast.IsPartOfTypeNode(node) && !ast.IsDeclarationName(node) {
			symbol := l.symbol(node)
			if symbol == owner || symbol == callback {
				callee := node
				for callee.Parent != nil && callee.Parent.Kind == ast.KindParenthesizedExpression {
					callee = callee.Parent
				}
				call := callee.Parent
				safe = safe && call != nil && call.Kind == ast.KindCallExpression && call.AsCallExpression().Expression == callee
				if symbol == owner {
					found = true
				}
			}
		}
		node.ForEachChild(visit)
		return false
	}
	for _, file := range l.program.Files() {
		file.AsNode().ForEachChild(visit)
	}
	return found && safe
}

func (l *lowering) predicateArguments(node *ast.Node) error {
	signature := l.checker.GetResolvedSignature(node)
	if signature == nil {
		return nil
	}
	if overload := signature.Declaration(); overload != nil && overload.Kind == ast.KindFunctionDeclaration && overload.Body() == nil && overload.Type() != nil && overload.Type().Kind == ast.KindTypePredicate {
		callee := ast.SkipParentheses(node.AsCallExpression().Expression)
		if callee.Kind != ast.KindIdentifier || l.symbol(callee) != l.symbol(overload.Name()) {
			return l.notYet(node, "an indirect call of a checked predicate overload")
		}
	}
	for index, parameter := range signature.Parameters() {
		if index >= len(node.AsCallExpression().Arguments.Nodes) {
			continue
		}
		var contract *ast.Node
		for _, declaration := range parameter.Declarations {
			if declaration.Kind == ast.KindParameter && declaration.Type() != nil && declaration.Type().Kind == ast.KindFunctionType && declaration.Type().Type() != nil && declaration.Type().Type().Kind == ast.KindTypePredicate {
				contract = declaration.Type().Type()
			}
		}
		if contract == nil {
			continue
		}
		argument := ast.SkipParentheses(node.AsCallExpression().Arguments.Nodes[index])
		implementation := argument
		if argument.Kind == ast.KindIdentifier {
			symbol := l.symbol(argument)
			if symbol != nil {
				for _, declaration := range symbol.Declarations {
					if ast.IsFunctionLike(declaration) && declaration.Body() != nil {
						implementation = declaration
					}
					if declaration.Kind == ast.KindVariableDeclaration && declaration.AsVariableDeclaration().Initializer != nil {
						implementation = ast.SkipParentheses(declaration.AsVariableDeclaration().Initializer)
					}
				}
			}
		}
		failure := func() error {
			file := ast.GetSourceFileOfNode(argument)
			text := file.Text()[scanner.GetTokenPosOfNode(argument, file, false):argument.End()]
			return &Refused{Where: l.program.Where(argument), What: "an unproven predicate argument for parameter " + parameter.Name + " (argument " + fmt.Sprintf("%q", text) + ")", Fix: "pass a named function or arrow whose body proves both predicate branches; return a boolean and narrow at the caller (adamic/no-type-predicate)"}
		}
		if !ast.IsFunctionLike(implementation) || implementation.Body() == nil || (implementation.Type() != nil && implementation.Type().Kind != ast.KindTypePredicate) {
			return failure()
		}
		if argument.Kind == ast.KindIdentifier {
			symbol := l.symbol(argument)
			changed := false
			var writes ast.Visitor
			writes = func(n *ast.Node) bool {
				if n.Kind == ast.KindIdentifier && l.symbol(n) == symbol && ast.IsAssignmentTarget(n) {
					changed = true
				}
				n.ForEachChild(writes)
				return false
			}
			for _, file := range l.program.Files() {
				file.AsNode().ForEachChild(writes)
			}
			if changed {
				return failure()
			}
		}
		wanted := contract.AsTypePredicateNode()
		calls := l.checker.GetSignaturesOfType(l.checker.GetTypeOfSymbol(parameter), checker.SignatureKindCall)
		var target *checker.Type
		if len(calls) == 1 {
			if predicate := predicateOfSignature(l.checker, calls[0]); predicate != nil {
				target = predicate.Type()
			}
		}
		if wanted.Type == nil || target == nil {
			return failure()
		}
		if implementation.Type() == nil {
			if !l.proveInferredPredicate(implementation, target) {
				return failure()
			}
		} else {
			annotation := implementation.Type().AsTypePredicateNode()
			if annotation.Type == nil || !checker.Checker_isTypeIdenticalTo(l.checker, l.checker.GetTypeAtLocation(annotation.Type), target) {
				return failure()
			}
			if err := l.predicateRefusal(implementation.Type()); err != nil {
				return failure()
			}
		}
	}
	return nil
}

// The pinned checker resolves a predicate's target under overload type arguments.
// This recovers the claim to validate; it never supplies a body-proof fact.
//
//go:linkname predicateOfSignature github.com/microsoft/TypeScript/tsc/internal/checker.(*Checker).getTypePredicateOfSignature
func predicateOfSignature(receiver *checker.Checker, signature *checker.Signature) *checker.TypePredicate

// Keep reference identity aligned with the pinned checker's flow analysis,
// including dotted/indexed spellings and stable computed indices.
//
//go:linkname predicateMatchingReference github.com/microsoft/TypeScript/tsc/internal/checker.(*Checker).isMatchingReference
func predicateMatchingReference(receiver *checker.Checker, source, target *ast.Node) bool

internal/lower/unknown.go:
package lower

import (
	"strings"

	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
)

func dynamicObjectType(proven *checker.Type) bool {
	if proven.Flags()&(checker.TypeFlagsUnknown|checker.TypeFlagsNonPrimitive) != 0 {
		return true
	}
	if proven.Flags()&(checker.TypeFlagsIntersection|checker.TypeFlagsUnion) != 0 {
		for _, part := range proven.Types() {
			if dynamicObjectType(part) {
				return true
			}
		}
	}
	return false
}

func (l *lowering) inProperty(node *ast.Node) (ir.Expression, error) {
	binary := node.AsBinaryExpression()
	key := ast.SkipParentheses(binary.Left)
	if key.Kind != ast.KindStringLiteral {
		return nil, l.notYet(key, "in with a key other than a string literal (dynamic key coercion)")
	}
	if strings.ContainsRune(key.Text(), 0) {
		return nil, l.notYet(key, "in with a NUL key (native shape names)")
	}
	// "key" in value narrows a union of object types to the members that declare the key, and any
	// object carrying that key passes, so the narrowed member's fields would be read on trust. The
	// sound use is presence on an unknown or single object type, where reads stay dynamic.
	if right := l.checker.GetNonNullableType(l.checker.GetTypeAtLocation(binary.Right)); right.Flags()&checker.TypeFlagsUnion != 0 {
		objects := 0
		for _, member := range right.Types() {
			if member.Flags()&checker.TypeFlagsObject != 0 {
				objects++
			}
		}
		if objects > 1 {
			return nil, &Refused{Where: l.program.Where(node), What: "in that narrows a union of object types (any object with the key passes)", Fix: "use a discriminant, or a Map"}
		}
	}
	if checker.IsTupleType(l.checker.GetNonNullableType(l.checker.GetTypeAtLocation(binary.Right))) {
		return nil, l.notYet(binary.Right, "in on a tuple (array presence metadata)")
	}
	if key.Text() == "stack" || key.Text() == "cause" || key.Text() == "errno" || key.Text() == "syscall" || key.Text() == "path" {
		return nil, l.notYet(key, "in on an Error internal or optional property (host descriptor metadata)")
	}
	if reason := l.presenceHazard(key.Text()); reason != "" {
		return nil, l.notYet(node, "in when "+reason)
	}
	if l.classes[l.symbol(ast.SkipParentheses(binary.Right))] != nil {
		return nil, l.notYet(binary.Right, "in on a class constructor (static property presence descriptors)")
	}
	object, err := l.expression(binary.Right)
	if err != nil {
		return nil, err
	}
	if object.Type() != ir.Object && object.Type() != ir.Array && object.Type() != ir.Union {
		return nil, l.notYet(binary.Right, "in on this runtime representation")
	}
	return ir.HasProperty{Object: fit(object, ir.Union), Name: key.Text()}, nil
}

func (l *lowering) dynamicProperty(node *ast.Node, object ir.Expression, name string) (ir.Expression, error) {
	if strings.ContainsRune(name, 0) {
		return nil, l.notYet(node, "a dynamic property name containing NUL (native shape names)")
	}
	if l.dynamicReadHazard(name) {
		return nil, l.notYet(node, "a dynamic getter or method read, or a nullable field (runtime dispatch, slot tags and narrowed rereads)")
	}
	// Prototype function values and dynamic array elements need callable and element metadata.
	switch name {
	case "constructor", "__proto__", "toString", "valueOf", "hasOwnProperty", "isPrototypeOf", "propertyIsEnumerable", "toLocaleString", "__defineGetter__", "__defineSetter__", "__lookupGetter__", "__lookupSetter__", "map", "filter", "push", "pop", "slice", "join", "entries", "values", "keys":
		return nil, l.notYet(node, "a dynamic prototype property value (intrinsic identity and ToPrimitive)")
	}
	value := ir.Expression(ir.DynamicProperty{Object: object, Name: name})
	of, err := l.typeOf(node)
	if err != nil {
		return nil, err
	}
	if of != ir.Union {
		value = ir.Narrow{Value: value, To: of}
	}
	return value, nil
}

// A dynamic read can be converted with String only when every program shape's field of that
// name is scalar. This is a conservative closed-program proof, not a promise from unknown.
func (l *lowering) dynamicScalarProperty(node *ast.Node) bool {
	node = ast.SkipParentheses(node)
	if ast.IsIdentifier(node) {
		symbol := l.symbol(node)
		if symbol != nil && len(symbol.Declarations) == 1 && symbol.Declarations[0].Kind == ast.KindVariableDeclaration {
			declaration := symbol.Declarations[0]
			if declaration.Parent.Flags&ast.NodeFlagsConst != 0 && declaration.AsVariableDeclaration().Initializer != nil {
				node = ast.SkipParentheses(declaration.AsVariableDeclaration().Initializer)
			}
		}
	}
	if node.Kind != ast.KindPropertyAccessExpression {
		return false
	}
	name := node.Name().Text()
	modules, err := l.moduleOrder(l.program.Files()[0])
	if err != nil {
		return false
	}
	known := true
	var visit ast.Visitor
	visit = func(candidate *ast.Node) bool {
		if candidate.Kind == ast.KindObjectLiteralExpression || candidate.Kind == ast.KindNewExpression || candidate.Kind == ast.KindArrayLiteralExpression {
			if field := l.checker.GetPropertyOfType(l.checker.GetTypeAtLocation(candidate), name); field != nil {
				proven := l.checker.GetTypeOfSymbol(field)
				if !l.writable(proven) {
					known = false
				}
			}
		}
		candidate.ForEachChild(visit)
		return false
	}
	for _, module := range modules {
		module.AsNode().ForEachChild(visit)
	}
	return known
}

// Unknown views must preserve runtime tags. Opaque host objects and tuples have additional
// JavaScript properties their native layouts do not yet describe.
func (l *lowering) unknownView(node *ast.Node, own, contextual *checker.Type) error {
	if !dynamicObjectType(contextual) {
		return nil
	}
	// Library intrinsics lower their arguments with their own schema or operation. Their
	// declaration's unknown parameter does not create an unknown runtime view.
	outer := node
	for outer.Parent != nil && outer.Parent.Kind == ast.KindParenthesizedExpression {
		outer = outer.Parent
	}
	if outer.Parent != nil && outer.Parent.Kind == ast.KindCallExpression {
		callee := outer.Parent.AsCallExpression().Expression
		if l.librarySymbol(l.memberSymbol(callee)) {
			return nil
		}
		if callee.Kind == ast.KindPropertyAccessExpression && callee.Name().Text() == "stringify" && l.isLibraryGlobal(callee.AsPropertyAccessExpression().Expression, "JSON") {
			return nil
		}
	}
	if l.includesNull(own) && own.Flags()&checker.TypeFlagsNull == 0 {
		if held, known := l.representation(own); known && held != ir.Union {
			return l.notYet(node, "a nullable reference viewed as unknown or object (null and undefined slot tags)")
		}
	}
	present := l.checker.GetNonNullableType(own)
	if held, known := l.representation(present); known && held == ir.Closure {
		return l.notYet(node, "a function viewed as unknown or object (dynamic function descriptors)")
	}
	for _, name := range []string{"JSON", "Math", "Reflect"} {
		if l.isLibraryGlobal(ast.SkipParentheses(node), name) {
			return l.notYet(node, "an intrinsic identity viewed as unknown or object (dynamic object descriptors)")
		}
	}
	for _, field := range l.checker.GetPropertiesOfType(present) {
		if l.includesNull(l.checker.GetTypeOfSymbol(field)) {
			return l.notYet(node, "an object with a nullable field viewed as unknown or object (null and undefined slot tags)")
		}
	}
	if checker.IsTupleType(present) {
		return l.notYet(node, "a tuple viewed as unknown or object (array presence metadata)")
	}
	if l.isLibraryType(present, "Map", "ReadonlyMap", "Set", "ReadonlySet", "RegExp", "Date", "Stats", "Hash", "Buffer") {
		return l.notYet(node, "an opaque host or collection value viewed as unknown or object (dynamic property metadata)")
	}
	return nil
}

// A key that could denote a getter or a prototype method cannot yet be read dynamically.
func (l *lowering) dynamicReadHazard(name string) bool {
	if l.accessorNames[name] {
		return true
	}
	for _, declaration := range l.classes {
		for _, member := range declaration.Members() {
			if member.Name() != nil && member.Name().Text() == name && member.Kind != ast.KindPropertyDeclaration {
				return true
			}
		}
	}
	modules, err := l.moduleOrder(l.program.Files()[0])
	if err != nil {
		return true
	}
	nullable := false
	var visit ast.Visitor
	visit = func(node *ast.Node) bool {
		if node.Kind == ast.KindObjectLiteralExpression || node.Kind == ast.KindNewExpression {
			if field := l.checker.GetPropertyOfType(l.checker.GetTypeAtLocation(node), name); field != nil && l.includesNull(l.checker.GetTypeOfSymbol(field)) {
				nullable = true
			}
		}
		node.ForEachChild(visit)
		return false
	}
	for _, module := range modules {
		module.AsNode().ForEachChild(visit)
	}
	return nullable
}

// Native absent-spread slots and ambient class fields are storage, not proof of JS presence.
func (l *lowering) presenceHazard(name string) string {
	modules, err := l.moduleOrder(l.program.Files()[0])
	if err != nil {
		return "runtime shapes are not known"
	}
	reason := ""
	var visit ast.Visitor
	visit = func(node *ast.Node) bool {
		if node.Kind == ast.KindObjectLiteralExpression {
			for _, property := range node.AsObjectLiteralExpression().Properties.Nodes {
				if property.Kind == ast.KindSpreadAssignment && l.includesUndefined(l.checker.GetTypeAtLocation(property.AsSpreadAssignment().Expression)) {
					reason = "a possibly absent spread has no property presence descriptors"
				}
			}
		}
		if node.Kind == ast.KindClassDeclaration {
			for _, member := range node.Members() {
				if member.Kind == ast.KindMethodDeclaration && member.Name().Text() == name {
					for _, parameter := range member.Parameters() {
						if held, known := l.representation(l.checker.GetTypeAtLocation(parameter.Name())); known && slotless(held) {
							reason = "a method's presence is not in its native dispatch table"
						}
					}
					for _, signature := range l.checker.GetSignaturesOfType(l.checker.GetTypeAtLocation(member), checker.SignatureKindCall) {
						if held, known := l.representation(l.checker.GetReturnTypeOfSignature(signature)); known && slotless(held) {
							reason = "a method's presence is not in its native dispatch table"
						}
					}
				}
				if member.Name() != nil && member.Name().Text() == name && ast.HasSyntacticModifier(member, ast.ModifierFlagsAmbient) {
					reason = "an ambient class field has no JavaScript own property"
				}
			}
		}
		node.ForEachChild(visit)
		return false
	}
	for _, module := range modules {
		module.AsNode().ForEachChild(visit)
	}
	return reason
}

internal/lower/lower.go:
// Package lower turns a checked program into Adamic's IR.
//
// Stage 0 lowers a little and refuses the rest. Every construct it can't lower yet is an error
// naming the construct and where it is, never a skip: a compiler that drops a statement it doesn't
// understand produces a program that looks right and isn't, which is the one thing Adamic must
// never do.
package lower

import (
	"context"
	"fmt"
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
	"github.com/system-inc/adamic/internal/load"
	"path/filepath"
)

// Lower lowers a checked program from one entry, in ESM evaluation order.
func Lower(ctx context.Context, program *load.Program) (*ir.Program, error) {
	files := program.Files()
	if len(files) != 1 {
		return nil, fmt.Errorf("lower: stage 0 compiles a program from one entry file, got %d", len(files))
	}
	entry := files[0]
	// Stage 0 checks single-threaded, so one checker answers for every file.
	typeChecker, release := program.Checker(ctx, entry)
	defer release()

	lowering := &lowering{program: program, checker: typeChecker, result: &ir.Program{}, this: -1, functionIndex: -1}
	// The base name only, so the same program emits the same C on every machine.
	lowering.result.Source = filepath.Base(program.FileName(entry))
	modules, err := lowering.moduleOrder(entry)
	if err != nil {
		return nil, err
	}
	lowering.noteInheritance(modules)
	if err := lowering.enumInitialization(modules); err != nil {
		return nil, err
	}
	lowering.noteAccessorNames(modules)
	lowering.noteOmittedOptionals(modules)
	if err := lowering.namespaceInitialization(modules); err != nil {
		return nil, err
	}
	for _, module := range modules {
		if err := lowering.refuse(module); err != nil {
			return nil, err
		}
	}
	// Link every declaration before lowering any function body, including across back edges.
	var declarations []*ast.Node
	for _, module := range modules {
		declarations = append(declarations, module.Statements.Nodes...)
	}
	if err := lowering.declareModule(declarations); err != nil {
		return nil, err
	}
	for _, module := range modules {
		body, err := lowering.statements(module.Statements.Nodes)
		if err != nil {
			return nil, err
		}
		lowering.result.Main = append(lowering.result.Main, body...)
	}
	if lowering.unlowerable != nil {
		return nil, lowering.unlowerable
	}
	lowering.result.Main = append(lowering.forwarderValues, lowering.result.Main...)
	lowering.finishClassCalls()
	if err := lowering.finishAccessors(); err != nil {
		return nil, err
	}
	if err := lowering.exceptions(); err != nil {
		return nil, err
	}
	if err := lowering.checkAccessorSpreads(); err != nil {
		return nil, err
	}
	if err := lowering.findCycles(modules); err != nil {
		return nil, err
	}
	readiness(lowering.result)
	borrow(lowering.result)
	counters(lowering.result)
	return lowering.result, nil
}

type lowering struct {
	// V2 retains exact logical producer types for union member certification.
	untaggedCallableTargets map[ir.ViewContractID]*checker.Type

	program *load.Program
	checker *checker.Checker
	result  *ir.Program

	// cyclicModules keeps unresolved reads checked throughout a cyclic graph.
	cyclicModules     bool
	provenModuleReads map[*ast.Node]bool
	cycleReadFindings []Finding

	// strings indexes result.Strings, so a constant used twice is stored once.
	strings map[string]int

	// locals maps each variable's symbol to its index in result.Locals.
	locals map[*ast.Symbol]int

	// functions maps each function declaration's symbol to its index in result.Functions.
	functions map[*ast.Symbol]int

	// function is the function being lowered, or nil for the module's top level.
	function *ir.Function

	// this is the local this is in a method or constructor, or -1.
	this int

	// functionIndex is the function being lowered, -1 for the module's top level, and closures the
	// closures being lowered, outermost first, each inside the one before.
	functionIndex int
	closures      []int

	// classes maps each module class's symbol to its declaration, and instances each instantiation
	// already lowered (class.go).
	// omittedOptionals is every optional property some object literal typed by its context leaves out:
	// that object has no slot for it (class.go's absentOptionalWrite).
	omittedOptionals map[*ast.Symbol]bool
	classes          map[*ast.Symbol]*ast.Node
	statics          map[*ast.Symbol]*instance
	staticGlobals    map[*ast.Symbol]int
	instances        map[string]*instance
	derivedAncestors map[*ast.Symbol]bool

	// privateOwners numbers each class that declares a private name, in the order first met, to
	// qualify its private members' names (privateName).
	privateOwners map[*ast.Node]int

	// instance is the class instantiation being lowered, if any.
	instance *instance

	// substitution is what each type parameter stands for in the instantiation being lowered.
	substitution map[*checker.Type]ir.Type

	// unlowerable is the first construct found not lowerable somewhere that can't return an error.
	unlowerable error

	// alwaysUndefined are parameters that only ever receive undefined, whatever the checker calls
	// their type: the first of an Array.from callback's (from.go). Each is a reference that's always
	// missing.
	alwaysUndefined map[*ast.Symbol]bool

	// signed are the functions whose signatures are written and whose bodies aren't lowered yet, by
	// index, each with what its body still needs (signature).
	signed map[int]signed

	// forwarders are the globals holding the function values made for module functions read as values,
	// by the function each forwards to, and forwarderValues the declarations that make them, which run
	// before anything else (functionValue).
	forwarders      map[int]int
	forwarderValues []ir.Statement

	// unsetUntil is where, in the constructor being lowered, its last assignment of a field without an
	// initializer ends: before it, this is only for reading and writing fields (useOfThis).
	unsetUntil int

	// generics maps each generic module function's symbol to its declaration, and genericInstances
	// each instantiation already lowered to its function (generic.go). genericDepth counts the
	// instantiations being lowered inside one another.
	generics              map[*ast.Symbol]*ast.Node
	genericInstances      map[string]int
	classGenericInstances map[string]map[string]int
	genericDepth          int

	// caught are the variables a catch binds, each always an Error; tries are the try statements
	// lowered (exceptions.go).
	caught map[*ast.Symbol]bool
	tries  []tryRecord

	// initializing is the variables whose initializers are being lowered, by where each is declared.
	initializing map[int]*ast.Node

	// For the cycle finder (cycles.go): the checker's type of each local, and where it's declared;
	// every function value made, with its type; and the class type being instantiated, for this.
	localTypes     map[int]*checker.Type
	localAlso      map[int][]*checker.Type
	localNodes     map[int]*ast.Node
	closureRecords []closureRecord
	classType      *checker.Type
	classNode      *ast.Node

	// typeMapper is what the type parameters of the instantiation being lowered, and of those it's
	// inside, stand for; instantiated is every class type an instantiation was made for (instantiate.go).
	typeMapper   *typeMapper
	instantiated []*checker.Type

	// writeSites is every write into a slot lowering made, by its IR node's Site less one (fresh.go).
	writeSites       []writeSite
	accessorCaptures []accessorCapture
	accessorNames    map[string]bool
}
